        assign hsync_vc9_sync  = (vcx_sync == 2'b10 && vc_sync == 2'b01 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc10_sync = (vcx_sync == 2'b10 && vc_sync == 2'b10 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc11_sync = (vcx_sync == 2'b10 && vc_sync == 2'b11 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc12_sync = (vcx_sync == 2'b11 && vc_sync == 2'b00 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc13_sync = (vcx_sync == 2'b11 && vc_sync == 2'b01 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc14_sync = (vcx_sync == 2'b11 && vc_sync == 2'b10 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc15_sync = (vcx_sync == 2'b11 && vc_sync == 2'b11 && (hsync_int || pixel_data_valid) && valid_video_datatype);
    end
    else begin
        assign hsync_vc0_sync  = hsync_vc_sync[0];
        assign hsync_vc1_sync  = hsync_vc_sync[1];
        assign hsync_vc2_sync  = hsync_vc_sync[2];
        assign hsync_vc3_sync  = hsync_vc_sync[3];
        assign hsync_vc4_sync  = hsync_vc_sync[4];
        assign hsync_vc5_sync  = hsync_vc_sync[5];
        assign hsync_vc6_sync  = hsync_vc_sync[6];
        assign hsync_vc7_sync  = hsync_vc_sync[7];
        assign hsync_vc8_sync  = hsync_vc_sync[8];
        assign hsync_vc9_sync  = hsync_vc_sync[9];
        assign hsync_vc10_sync = hsync_vc_sync[10];
        assign hsync_vc11_sync = hsync_vc_sync[11];
        assign hsync_vc12_sync = hsync_vc_sync[12];
        assign hsync_vc13_sync = hsync_vc_sync[13];
        assign hsync_vc14_sync = hsync_vc_sync[14];
        assign hsync_vc15_sync = hsync_vc_sync[15];
    end
end
else begin
    assign vsync_vc0_sync  = vsync_vc_sync[0];
    assign vsync_vc1_sync  = vsync_vc_sync[1];
    assign vsync_vc2_sync  = vsync_vc_sync[2];
    assign vsync_vc3_sync  = vsync_vc_sync[3];

	if (FRAME_MODE == "GENERIC") begin
        // during FRAME_MODE = "GENERIC", hsync depends on pixel_data_valid
        assign hsync_vc0_sync  = (vc_sync == 2'b00 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc1_sync  = (vc_sync == 2'b01 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc2_sync  = (vc_sync == 2'b10 && (hsync_int || pixel_data_valid) && valid_video_datatype);
        assign hsync_vc3_sync  = (vc_sync == 2'b11 && (hsync_int || pixel_data_valid) && valid_video_datatype);
    end
    else begin
        assign hsync_vc0_sync  = hsync_vc_sync[0];
        assign hsync_vc1_sync  = hsync_vc_sync[1];
        assign hsync_vc2_sync  = hsync_vc_sync[2];
        assign hsync_vc3_sync  = hsync_vc_sync[3];
    end
    
    assign vsync_vc4_sync  = 1'b0;
    assign vsync_vc5_sync  = 1'b0;
    assign vsync_vc6_sync  = 1'b0;
    assign vsync_vc7_sync  = 1'b0;
    assign vsync_vc8_sync  = 1'b0;
    assign vsync_vc9_sync  = 1'b0;
    assign vsync_vc10_sync = 1'b0;
    assign vsync_vc11_sync = 1'b0;
    assign vsync_vc12_sync = 1'b0;
    assign vsync_vc13_sync = 1'b0;
    assign vsync_vc14_sync = 1'b0;
    assign vsync_vc15_sync = 1'b0;
    assign hsync_vc4_sync  = 1'b0;
    assign hsync_vc5_sync  = 1'b0;
    assign hsync_vc6_sync  = 1'b0;
    assign hsync_vc7_sync  = 1'b0;
    assign hsync_vc8_sync  = 1'b0;
    assign hsync_vc9_sync  = 1'b0;
    assign hsync_vc10_sync = 1'b0;
    assign hsync_vc11_sync = 1'b0;
    assign hsync_vc12_sync = 1'b0;
    assign hsync_vc13_sync = 1'b0;
    assign hsync_vc14_sync = 1'b0;
    assign hsync_vc15_sync = 1'b0;
end
endgenerate

assign fifo_read = fifo_read_40bit || fifo_read_48bit || fifo_read_56bit || fifo_read_64bit;
assign pixel_data_valid = pixel_data_valid_40bit || pixel_data_valid_48bit || pixel_data_valid_56bit || pixel_data_valid_64bit;
assign depack_40bit = (RAW10_sync || YUV_420_10_sync || YUV_422_10_sync || RAW20_sync);
assign depack_48bit = (RAW6_sync || RAW12_sync || RGB888_sync || YUV_420_8_legacy_sync);
assign depack_56bit = (RAW7_sync || RAW14_sync);
assign depack_64bit = (RAW8_sync || YUV_422_8_sync || RGB444_sync || RGB555_sync || RGB565_sync || YUV_420_8_sync || user_define_8bit_sync || gen_long_pkt_sync || embed_8bit_nonvideo_sync);
assign pixel_data = (depack_48bit) ? pixel_data_48bit :
	                  (depack_56bit) ? pixel_data_56bit :
	                    (depack_64bit) ? pixel_data_64bit :
	                      (depack_40bit) ? pixel_data_40bit : 64'd0;
	                      
assign valid_depack_40bit = !fifo_empty && (depack_40bit) && start_fifo_read;
assign valid_depack_48bit = !fifo_empty && (depack_48bit) && start_fifo_read;
assign valid_depack_56bit = !fifo_empty && (depack_56bit) && start_fifo_read;
assign valid_depack_64bit = !fifo_empty && (depack_64bit) && start_fifo_read;

always @(posedge clk_pixel or negedge reset_pixel_n) 
begin
    if (!reset_pixel_n) begin
    	pixel_bits_cnt         <= 19'd0;
    end
    else if (~prog_empty_o && prog_empty_o_reg) begin //pixel_bits_cnt == 19'd0) begin //start read only after at least 2 FIFO depth is filled
    	pixel_bits_cnt         <= total_pixel_bits;
    end
    else if (valid_depack_40bit && (pixel_bits_cnt >= 19'd40)) begin
    	pixel_bits_cnt         <= pixel_bits_cnt - 19'd40;
    end
    else if (valid_depack_48bit && (pixel_bits_cnt >= 19'd48)) begin
    	pixel_bits_cnt         <= pixel_bits_cnt - 19'd48;
    end
    else if (valid_depack_56bit && (pixel_bits_cnt >= 19'd56)) begin
    	pixel_bits_cnt         <= pixel_bits_cnt - 19'd56;
    end
    else if (valid_depack_64bit && (pixel_bits_cnt >= 19'd64)) begin
    	pixel_bits_cnt         <= pixel_bits_cnt - 19'd64;
    end
    else if (((reset_pix_cnt_40bit || valid_depack_40bit) && depack_40bit && (pixel_bits_cnt < 19'd40)) || ((reset_pix_cnt_48bit || valid_depack_48bit) && depack_48bit && (pixel_bits_cnt < 19'd48)) || 
        ((reset_pix_cnt_56bit || valid_depack_56bit) && depack_56bit && (pixel_bits_cnt < 19'd56)) || (valid_depack_64bit && depack_64bit && (pixel_bits_cnt < 19'd64))) begin //for 64bit, need to AND with valid because no FSM
    	pixel_bits_cnt         <= 19'd0;
    end
end
//start read only after at least 2 FIFO depth is filled
always @(posedge clk_pixel or negedge reset_pixel_n) 
begin
    if (!reset_pixel_n) begin
    	start_fifo_read    <= 1'b0;
    end
    else if (~prog_empty_o && prog_empty_o_reg) begin
    	start_fifo_read    <= 1'b1;
    end
    else if (pixel_bits_cnt == 19'd0) begin
    	start_fifo_read    <= 1'b0;
    end
end

always @(posedge clk_pixel or negedge reset_pixel_n) 
begin
    if (!reset_pixel_n) begin
    	hsync_int              <= 1'b0;
    	prog_empty_o_reg        <= 1'b0;
    	pixel_data_valid_reg    <= 1'b0;
    end
    else begin
        prog_empty_o_reg        <= prog_empty_o;
    	pixel_data_valid_reg    <= pixel_data_valid;
    	
        if (pixel_data_valid && ~pixel_data_valid_reg) begin
        	hsync_int    <= 1'b1;
        end
        else if (pixel_bits_cnt == 19'd0) begin
        	hsync_int    <= 1'b0;
        end
    end
end
	 
always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if(!reset_pixel_n) begin
        extra_pixel_count    <= 4'd0;
    end
    else begin
    	// depack 64bit 
    	if (pixel_bits_cnt < 19'd64 && pixel_bits_cnt > 19'd0 && (RAW8_sync || (YUV_420_8_sync && odd_line_sync) || user_define_8bit_sync || gen_long_pkt_sync || embed_8bit_nonvideo_sync)) begin
            extra_pixel_count         <= extra_pixel;  //1 byte = 1 pixel
        end
        // depack 64bit 
        else if (pixel_bits_cnt < 19'd64 && pixel_bits_cnt > 19'd0 && (RGB444_sync || YUV_422_8_sync || RGB555_sync || RGB565_sync || (YUV_420_8_sync && ~odd_line_sync))) begin
            extra_pixel_count         <= extra_pixel/2;  //2 bytes = 1 pixel
        end
        // depack 56bit 
        else if (pixel_bits_cnt < 19'd56 && pixel_bits_cnt > 19'd0 && (RAW7_sync)) begin
            extra_pixel_count         <= (extra_pixel/7) << 3;  //7 bytes = 8 pixel
        end
        // depack 56bit 
        else if (pixel_bits_cnt < 19'd56 && pixel_bits_cnt > 19'd0 && (RAW14_sync)) begin
            extra_pixel_count         <= (extra_pixel/7) << 2;  //7 bytes = 4 pixel
        end
        // depack 48bit 
        else if (pixel_bits_cnt < 19'd48 && pixel_bits_cnt > 19'd0 && (RAW6_sync)) begin
            extra_pixel_count         <= (extra_pixel/3) << 2;  //6 bytes = 8 pixel (3 bytes = 4 pixel)
        end
        // depack 48bit 
        else if (pixel_bits_cnt < 19'd48 && pixel_bits_cnt > 19'd0 && (RAW12_sync || YUV_420_8_legacy_sync)) begin
            extra_pixel_count         <= (extra_pixel/3) << 1;  //6 bytes = 4 pixel (3 bytes = 2 pixel)
        end
        // depack 48bit 
        else if (pixel_bits_cnt < 19'd48 && pixel_bits_cnt > 19'd0 && (RGB888_sync)) begin
            extra_pixel_count         <= (extra_pixel/3);  //6 bytes = 2 pixel (3 bytes = 1 pixel)
        end
        // depack 40bit 
        else if (pixel_bits_cnt < 19'd40 && pixel_bits_cnt > 19'd0 && (RAW10_sync || (YUV_420_10_sync && odd_line_sync))) begin
            extra_pixel_count         <= (extra_pixel/5) << 2;  //5 bytes = 4 pixel
        end
        // depack 40bit 
        else if (pixel_bits_cnt < 19'd40 && pixel_bits_cnt > 19'd0 && (YUV_422_10_sync || (YUV_420_10_sync && ~odd_line_sync))) begin
            extra_pixel_count         <= (extra_pixel/5) << 1;  //5 bytes = 2 pixel
        end
        else begin
            extra_pixel_count    <= 4'd0;
        end
    end
end

