// synopsys translate_off
`timescale 1 ns / 1 ps													
// synopsys translate_on
// polynomial: x^16 + x^12 + x^5 + 1
// Algorithm: CRC-16/MCRF4XX
// reverce CRC and input
module `IP_MODULE_NAME(efx_csi2_crc16_d8_gen)(
    input                 clk,
    input                 rst_n,
    input                 crc8_en,
    input [7:0]           din,
    input                 clr_crc,
    output logic [15:0]   crc              
);

logic [15:0]    reverse_crc, reverse_crc_r;
logic [7:0]     reverse_8din, reverse_8din_r;
logic crc8_en_r;

assign reverse_8din = {din[0], din[1], din[2], din[3], din[4], din[5], din[6], din[7]};
                      
assign crc = {reverse_crc[0], reverse_crc[1], reverse_crc[2], reverse_crc[3], reverse_crc[4], reverse_crc[5], reverse_crc[6], reverse_crc[7], 
              reverse_crc[8], reverse_crc[9], reverse_crc[10], reverse_crc[11], reverse_crc[12], reverse_crc[13], reverse_crc[14], reverse_crc[15]};
  
    // polynomial: x^16 + x^12 + x^5 + 1
  // data width: 8
  // convention: the first serial bit is D[7]
  function [15:0] nextCRC16_D8;

    input [7:0] Data;
    input [15:0] crc;
    reg [7:0] d;
    reg [15:0] c;
    reg [15:0] newcrc;
  begin
    d = Data;
    c = crc;

    newcrc[0] = d[4] ^ d[0] ^ c[8] ^ c[12];
    newcrc[1] = d[5] ^ d[1] ^ c[9] ^ c[13];
    newcrc[2] = d[6] ^ d[2] ^ c[10] ^ c[14];
    newcrc[3] = d[7] ^ d[3] ^ c[11] ^ c[15];
    newcrc[4] = d[4] ^ c[12];
    newcrc[5] = d[5] ^ d[4] ^ d[0] ^ c[8] ^ c[12] ^ c[13];
    newcrc[6] = d[6] ^ d[5] ^ d[1] ^ c[9] ^ c[13] ^ c[14];
    newcrc[7] = d[7] ^ d[6] ^ d[2] ^ c[10] ^ c[14] ^ c[15];
    newcrc[8] = d[7] ^ d[3] ^ c[0] ^ c[11] ^ c[15];
    newcrc[9] = d[4] ^ c[1] ^ c[12];
    newcrc[10] = d[5] ^ c[2] ^ c[13];
    newcrc[11] = d[6] ^ c[3] ^ c[14];
    newcrc[12] = d[7] ^ d[4] ^ d[0] ^ c[4] ^ c[8] ^ c[12] ^ c[15];
    newcrc[13] = d[5] ^ d[1] ^ c[5] ^ c[9] ^ c[13];
    newcrc[14] = d[6] ^ d[2] ^ c[6] ^ c[10] ^ c[14];
    newcrc[15] = d[7] ^ d[3] ^ c[7] ^ c[11] ^ c[15];
    nextCRC16_D8 = newcrc;
  end
  endfunction
/*
always @ (posedge clk or negedge rst_n)
begin
    if (!rst_n) begin
        reverse_crc <= 16'hffff;
    end
    else if (clr_crc) begin
        reverse_crc <= 16'hffff;
    end
    else if (crc8_en) begin
        reverse_crc <= nextCRC16_D8(reverse_8din, reverse_crc);
    end
end*/

always @ (posedge clk or negedge rst_n)
begin
    if (!rst_n) begin
        reverse_8din_r  <= 8'h0;
    end
    else begin
        reverse_8din_r  <= reverse_8din;
    end
end

always @ (posedge clk or negedge rst_n)
begin
    if (!rst_n) begin
        reverse_crc_r <= 16'hffff;
        crc8_en_r     <= 1'b0;
    end
    else begin
        reverse_crc_r <= reverse_crc;
        crc8_en_r     <= crc8_en;
    end
end

assign reverse_crc = crc8_en_r ? nextCRC16_D8(reverse_8din_r, reverse_crc_r) : 
                     clr_crc ? 16'hffff : reverse_crc_r;
endmodule






// synopsys translate_off
`timescale 1 ns / 1 ps													
// synopsys translate_on
// polynomial: x^16 + x^12 + x^5 + 1
// Algorithm: CRC-16/MCRF4XX
// reverce CRC and input
module `IP_MODULE_NAME(efx_csi2_crc16_d16_gen)(
    input                 clk,
    input                 rst_n,
    input                 crc8_en, 
    input                 crc16_en,
    input [15:0]          din,
    input                 clr_crc,
    output logic [15:0]   crc           
);

logic [15:0]    reverse_crc, reverse_crc_r;
logic [15:0]    reverse_16din, reverse_16din_r;
logic [7:0]     reverse_8din, reverse_8din_r;
logic crc16_en_r, crc8_en_r;

assign reverse_16din = {din[0], din[1], din[2], din[3], din[4], din[5], din[6], din[7],
                      din[8], din[9], din[10], din[11], din[12], din[13], din[14], din[15]};
                      
assign reverse_8din = {din[0], din[1], din[2], din[3], din[4], din[5], din[6], din[7]};
                      
assign crc = {reverse_crc[0], reverse_crc[1], reverse_crc[2], reverse_crc[3], reverse_crc[4], reverse_crc[5], reverse_crc[6], reverse_crc[7], 
              reverse_crc[8], reverse_crc[9], reverse_crc[10], reverse_crc[11], reverse_crc[12], reverse_crc[13], reverse_crc[14], reverse_crc[15]};
  
  // polynomial: x^16 + x^12 + x^5 + 1
  // data width: 16
  // convention: the first serial bit is D[15]
  function [15:0] nextCRC16_D16;

    input [15:0] Data;
    input [15:0] crc;
    reg [15:0] d;
    reg [15:0] c;
    reg [15:0] newcrc;
  begin
    d = Data;
    c = crc;

    newcrc[0] = d[12] ^ d[11] ^ d[8] ^ d[4] ^ d[0] ^ c[0] ^ c[4] ^ c[8] ^ c[11] ^ c[12];
    newcrc[1] = d[13] ^ d[12] ^ d[9] ^ d[5] ^ d[1] ^ c[1] ^ c[5] ^ c[9] ^ c[12] ^ c[13];
