always @ (posedge clk or negedge rst_n)
begin
    if (!rst_n) begin
        reverse_32din_r <= 32'h0;
        reverse_24din_r <= 24'h0;
        reverse_16din_r <= 16'h0;
        reverse_8din_r  <= 8'h0;
    end
    else begin
        reverse_32din_r <= reverse_32din;
        reverse_24din_r <= reverse_24din;
        reverse_16din_r <= reverse_16din;
        reverse_8din_r  <= reverse_8din;
    end
end

always @ (posedge clk or negedge rst_n)
begin
    if (!rst_n) begin
        reverse_crc_r <= 16'hffff;
        crc32_en_r    <= 1'b0;
        crc24_en_r    <= 1'b0;
        crc16_en_r    <= 1'b0;
        crc8_en_r     <= 1'b0;
    end
    else begin
        reverse_crc_r <= reverse_crc;
        crc32_en_r    <= crc32_en;
        crc24_en_r    <= crc24_en;
        crc16_en_r    <= crc16_en;
        crc8_en_r     <= crc8_en;
    end
end

assign reverse_crc = crc32_en_r ? nextCRC16_D32(reverse_32din_r, reverse_crc_r) : 
                     crc24_en_r ? nextCRC16_D24(reverse_24din_r, reverse_crc_r) :
                     crc16_en_r ? nextCRC16_D16(reverse_16din_r, reverse_crc_r) :
                     crc8_en_r ? nextCRC16_D8(reverse_8din_r, reverse_crc_r) : 
                     clr_crc ? 16'hffff : reverse_crc_r;
                     
endmodule





