// synopsys translate_off
`timescale 1 ns / 1 ps													
// synopsys translate_on

module `IP_MODULE_NAME(efx_csi2_depack40bit) (
    input               clk_pixel,
    input               reset_pixel_n,
    input  logic        RAW20_r,
    input  logic [63:0] pixel_data_i,
    input  logic [18:0] pixel_bits_cnt,
    input  logic        trigger_extra_pix,
    output logic        reset_pix_cnt,
    output logic        fifo_read,
    output logic [63:0] pixel_data_o,
    output logic        pixel_data_valid,
    input  logic        valid_depack
);

localparam [3:0] ST_1ST_PACK = 4'b0000;
localparam [3:0] ST_2ND_PACK = 4'b0001;
localparam [3:0] ST_3RD_PACK = 4'b0010;
localparam [3:0] ST_4TH_PACK = 4'b0011;
localparam [3:0] ST_5TH_PACK = 4'b0100;
localparam [3:0] ST_6TH_PACK = 4'b0101;
localparam [3:0] ST_7TH_PACK = 4'b0110;
localparam [3:0] ST_8TH_PACK = 4'b0111;

localparam PACK_BYTE = 40;
localparam FULL_BYTE = 64;

logic [FULL_BYTE-1:0] pixel_data_i_p1, pixel_data_i_p2;
logic [PACK_BYTE-1:0] pixel_data;
logic [3:0] fsm_state, next_state;

assign pixel_data_o = {24'd0, pixel_data};

assign fifo_read = (valid_depack && ((fsm_state == ST_1ST_PACK) || (fsm_state == ST_3RD_PACK) ||
                                  (fsm_state == ST_4TH_PACK) || (fsm_state == ST_6TH_PACK) || (fsm_state == ST_8TH_PACK)));
assign reset_pix_cnt = (pixel_bits_cnt < PACK_BYTE) && (fsm_state == ST_2ND_PACK || fsm_state == ST_5TH_PACK || fsm_state == ST_7TH_PACK);                         

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		next_state         <= ST_1ST_PACK;
	end
	else begin
		next_state         <= fsm_state;
	end
end

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		pixel_data_i_p1         <= {FULL_BYTE{1'b0}};
		pixel_data_i_p2         <= {FULL_BYTE{1'b0}};
	end
	else begin
		pixel_data_i_p1         <= pixel_data_i;
		pixel_data_i_p2         <= pixel_data_i_p1;
	end
end

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		pixel_data_valid         <= 1'b0;
	end
	else if ((valid_depack && pixel_bits_cnt > 19'd0) || (~valid_depack && ((fsm_state == ST_2ND_PACK || fsm_state == ST_5TH_PACK || fsm_state == ST_7TH_PACK) && trigger_extra_pix))) begin
		pixel_data_valid         <= 1'b1;
	end
	else begin
		pixel_data_valid         <= 1'b0;
	end
end

// rearrange the pixel byte accoring to datatype
assign raw_20_1 = {pixel_data_i[7:0], pixel_data_i[39:38], pixel_data_i[15:8], pixel_data_i[37:36]};
assign raw_20_2 = {pixel_data_i[23:16], pixel_data_i[35:34], pixel_data_i[31:24], pixel_data_i[33:32]};

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		fsm_state    <= ST_1ST_PACK;
		pixel_data   <= {PACK_BYTE{1'b0}};
	end
	else begin
        case(fsm_state)
        	ST_1ST_PACK : begin  // use for YUV_422_10bit, YUV_420_10bit, raw10, RAW20
                if (RAW20_r) begin
        	        pixel_data     <= {pixel_data_i[23:16], pixel_data_i[37:36], pixel_data_i[15:8], pixel_data_i[39:38], 
        	                           pixel_data_i[7:0], pixel_data_i[33:32], pixel_data_i[15:8], pixel_data_i[35:34]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[31:24], pixel_data_i[39:38], pixel_data_i[23:16], pixel_data_i[37:36], pixel_data_i[15:8], pixel_data_i[35:34], pixel_data_i[7:0], pixel_data_i[33:32]};
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_2ND_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end	
            end
            
        	ST_2ND_PACK : begin
                if (RAW20_r) begin
        	        pixel_data     <= {pixel_data_i_p1[63:56], pixel_data_i[13:12], pixel_data_i[7:0], pixel_data_i[15:14], 
        	                           pixel_data_i_p1[47:40], pixel_data_i[9:8], pixel_data_i_p1[55:48], pixel_data_i[11:10]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[7:0], pixel_data_i[15:14], pixel_data_i_p1[63:56], pixel_data_i[13:12], pixel_data_i_p1[55:48], pixel_data_i[11:10], pixel_data_i_p1[47:40], pixel_data_i[9:8]};
        	    end
        	        
         	    if (valid_depack) begin
                    fsm_state    <= ST_3RD_PACK;
                end	
        	     else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end		
            end
            
        	ST_3RD_PACK : begin
                if (RAW20_r) begin
        	        pixel_data     <= {pixel_data_i_p1[39:32], pixel_data_i_p1[53:52], pixel_data_i_p1[47:40], pixel_data_i_p1[55:54], 
        	                           pixel_data_i_p1[23:16], pixel_data_i_p1[49:48], pixel_data_i_p1[31:24], pixel_data_i_p1[51:50]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i_p1[47:40], pixel_data_i_p1[55:54], pixel_data_i_p1[39:32], pixel_data_i_p1[53:52], pixel_data_i_p1[31:24], pixel_data_i_p1[51:50], pixel_data_i_p1[23:16], pixel_data_i_p1[49:48]};
        	    end
        	    
         	    if (valid_depack) begin
                    fsm_state    <= ST_4TH_PACK;
                end	
        	     else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end	
            end
            
        	ST_4TH_PACK : begin
                if (RAW20_r) begin
        	        pixel_data     <= {pixel_data_i[15:8], pixel_data_i[29:28], pixel_data_i[23:16], pixel_data_i[31:30], 
        	                           pixel_data_i_p2[63:56], pixel_data_i[25:24], pixel_data_i[7:0], pixel_data_i[27:26]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[23:16], pixel_data_i[31:30], pixel_data_i[15:8], pixel_data_i[29:28], pixel_data_i[7:0], pixel_data_i[27:26], pixel_data_i_p2[63:56], pixel_data_i[25:24]};
        	    end
        	    
         	    if (valid_depack) begin
                    fsm_state    <= ST_5TH_PACK;
                end	
        	     else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end	
            end
            
        	ST_5TH_PACK : begin
                if (RAW20_r) begin
        	        pixel_data     <= {pixel_data_i_p1[55:48], pixel_data_i[5:4], pixel_data_i_p1[63:56], pixel_data_i[7:6], 
        	                           pixel_data_i_p1[39:32], pixel_data_i[1:0], pixel_data_i_p1[47:40], pixel_data_i[3:2]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i_p1[63:56], pixel_data_i[7:6], pixel_data_i_p1[55:48], pixel_data_i[5:4], pixel_data_i_p1[47:40], pixel_data_i[3:2], pixel_data_i_p1[39:32], pixel_data_i[1:0]};
        	    end
        	    
         	    if (valid_depack) begin
                    fsm_state    <= ST_6TH_PACK;
                end	
        	     else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end	
            end
            
        	ST_6TH_PACK : begin
                if (RAW20_r) begin
        	        pixel_data     <= {pixel_data_i_p1[31:24], pixel_data_i_p1[45:44], pixel_data_i_p1[39:32], pixel_data_i_p1[47:46], 
        	                           pixel_data_i_p1[15:8], pixel_data_i_p1[41:40], pixel_data_i_p1[23:16], pixel_data_i_p1[43:42]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i_p1[39:32], pixel_data_i_p1[47:46], pixel_data_i_p1[31:24], pixel_data_i_p1[45:44], pixel_data_i_p1[23:16], pixel_data_i_p1[43:42], pixel_data_i_p1[15:8], pixel_data_i_p1[41:40]};
        	    end
        	    
         	    if (valid_depack) begin
                    fsm_state    <= ST_7TH_PACK;
                end	
        	     else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end	
            end
            
        	ST_7TH_PACK : begin
                if (RAW20_r) begin
        	        pixel_data     <= {pixel_data_i[7:0], pixel_data_i[21:20], pixel_data_i[15:8], pixel_data_i[23:22], 
        	                           pixel_data_i_p2[55:48], pixel_data_i[17:16], pixel_data_i_p2[63:56], pixel_data_i[19:18]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[15:8], pixel_data_i[23:22], pixel_data_i[7:0], pixel_data_i[21:20], pixel_data_i_p2[63:56], pixel_data_i[19:18], pixel_data_i_p2[55:48], pixel_data_i[17:16]};
        	    end
        	    
         	    if (valid_depack) begin
                    fsm_state    <= ST_8TH_PACK;
                end	
        	     else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
        	ST_8TH_PACK : begin
                if (RAW20_r) begin
        	        pixel_data     <= {pixel_data_i_p1[47:40], pixel_data_i_p1[61:60], pixel_data_i_p1[55:48], pixel_data_i_p1[63:62], 
        	                           pixel_data_i_p1[31:24], pixel_data_i_p1[57:56], pixel_data_i_p1[39:32], pixel_data_i_p1[59:58]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i_p1[55:48], pixel_data_i_p1[63:62], pixel_data_i_p1[47:40], pixel_data_i_p1[61:60], pixel_data_i_p1[39:32], pixel_data_i_p1[59:58], pixel_data_i_p1[31:24], pixel_data_i_p1[57:56]};
        	    end
        	    
        	    fsm_state    <= ST_1ST_PACK;
            end
            default : begin 
                fsm_state    <= ST_1ST_PACK; 
                pixel_data <= {PACK_BYTE{1'b0}};
            end
        endcase
    end
end

endmodule


// synopsys translate_off
`timescale 1 ns / 1 ps													
// synopsys translate_on

module `IP_MODULE_NAME(efx_csi2_depack48bit) (
    input  logic        clk_pixel,
    input  logic        reset_pixel_n,
    input  logic        RAW12_r,
    input  logic        YUV_420_8_legacy_r,
    input  logic [63:0] pixel_data_i,
    input  logic [18:0] pixel_bits_cnt,
    input  logic        trigger_extra_pix,
    output logic        reset_pix_cnt,
    output logic        fifo_read,
    output logic [63:0] pixel_data_o,
    output logic        pixel_data_valid,
    input  logic        valid_depack
);

localparam [2:0] ST_1ST_PACK = 3'b000;
localparam [2:0] ST_2ND_PACK = 3'b001;
localparam [2:0] ST_3RD_PACK = 3'b010;
localparam [2:0] ST_4TH_PACK = 3'b011;

localparam PACK_BYTE = 48;
localparam FULL_BYTE = 64;

logic [FULL_BYTE-1:0] pixel_data_i_p1;
logic [PACK_BYTE-1:0] pixel_data;
logic [2:0] fsm_state, next_state;

assign pixel_data_o = {16'd0, pixel_data};

assign fifo_read = (valid_depack && (fsm_state != ST_3RD_PACK));
assign reset_pix_cnt = (pixel_bits_cnt < PACK_BYTE) && (fsm_state == ST_3RD_PACK);

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		next_state         <= ST_1ST_PACK;
	end
	else begin
		next_state         <= fsm_state;
	end
end

always @(posedge clk_pixel or negedge reset_pixel_n) 
begin
    if (!reset_pixel_n) begin
        pixel_data_i_p1    <= {FULL_BYTE{1'b0}};
    end
    else begin
        pixel_data_i_p1    <= pixel_data_i;
    end
end

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		pixel_data_valid         <= 1'b0;
	end
	else if ((valid_depack && pixel_bits_cnt > 19'd0)  || (~valid_depack && fsm_state == ST_3RD_PACK && trigger_extra_pix)) begin
		pixel_data_valid         <= 1'b1;
	end
	else begin
		pixel_data_valid         <= 1'b0;
	end
end

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		fsm_state    <= ST_1ST_PACK;
		pixel_data   <= {PACK_BYTE{1'b0}};
	end
	else begin
        case(fsm_state)
        	ST_1ST_PACK : begin
        	    if (RAW12_r) begin
        	        pixel_data     <= {pixel_data_i[39:32], pixel_data_i[47:44], pixel_data_i[31:24], pixel_data_i[43:40],
        	                            pixel_data_i[15:8], pixel_data_i[23:20], pixel_data_i[7:0], pixel_data_i[19:16]};
        	    end
        	    else begin
        	        pixel_data     <= pixel_data_i[PACK_BYTE-1:0];
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_2ND_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end	
            end
            
        	ST_2ND_PACK : begin
        	    if (RAW12_r) begin
        	        pixel_data     <= {pixel_data_i[23:16], pixel_data_i[31:28], pixel_data_i[15:8], pixel_data_i[27:24],
        	                            pixel_data_i_p1[63:56], pixel_data_i[7:4], pixel_data_i_p1[55:48], pixel_data_i[3:0]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[31:0], pixel_data_i_p1[FULL_BYTE-1:48]};
        	    end

         	    if (valid_depack) begin
                    fsm_state    <= ST_3RD_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end	
            end
            
        	ST_3RD_PACK : begin
        	    if (RAW12_r) begin
        	        pixel_data     <= {pixel_data_i[7:0], pixel_data_i[15:12], pixel_data_i_p1[63:56], pixel_data_i[11:8],
        	                            pixel_data_i_p1[47:40], pixel_data_i_p1[55:52], pixel_data_i_p1[39:32], pixel_data_i_p1[51:48]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[15:0], pixel_data_i_p1[FULL_BYTE-1:32]};
        	    end

        	    if (valid_depack) begin
                    fsm_state    <= ST_4TH_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
        	ST_4TH_PACK : begin
        	    if (RAW12_r) begin
        	        pixel_data     <= {pixel_data_i_p1[55:48], pixel_data_i[63:60], pixel_data_i_p1[47:40], pixel_data_i[59:56],
        	                            pixel_data_i_p1[31:24], pixel_data_i_p1[39:36], pixel_data_i_p1[23:16], pixel_data_i_p1[35:32]};
        	    end
        	    else begin
        	        pixel_data     <= pixel_data_i_p1[FULL_BYTE-1:16];
        	    end
        	    
                fsm_state    <= ST_1ST_PACK;
            end
            default : begin 
                fsm_state    <= ST_1ST_PACK; 
                pixel_data   <= {PACK_BYTE{1'b0}};
            end
        endcase
    end
end

endmodule


