`timescale 1 ns / 1 ps													
// synopsys translate_on

module `IP_MODULE_NAME(efx_csi2_depack56bit) (
    input               clk_pixel,
    input               reset_pixel_n,
    input  logic        RAW14_r,
    input  logic [63:0] pixel_data_i,
    input  logic [18:0] pixel_bits_cnt,
    input  logic        trigger_extra_pix,
    output logic        reset_pix_cnt,
    output logic        fifo_read,
    output logic [63:0] pixel_data_o,
    output logic        pixel_data_valid,
    input  logic        valid_depack
);

localparam [3:0] ST_1ST_PACK = 4'b0000;
localparam [3:0] ST_2ND_PACK = 4'b0001;
localparam [3:0] ST_3RD_PACK = 4'b0010;
localparam [3:0] ST_4TH_PACK = 4'b0011;
localparam [3:0] ST_5TH_PACK = 4'b0100;
localparam [3:0] ST_6TH_PACK = 4'b0101;
localparam [3:0] ST_7TH_PACK = 4'b0110;
localparam [3:0] ST_8TH_PACK = 4'b0111;

localparam PACK_BYTE = 56;
localparam FULL_BYTE = 64;

logic [FULL_BYTE-1:0] pixel_data_i_p1;
logic [PACK_BYTE-1:0] pixel_data;
logic [3:0] fsm_state, next_state;

assign pixel_data_o = {8'd0, pixel_data};

assign fifo_read = (valid_depack && (fsm_state != ST_7TH_PACK));
assign reset_pix_cnt = (pixel_bits_cnt < PACK_BYTE) && (fsm_state == ST_7TH_PACK);

always @(posedge clk_pixel or negedge reset_pixel_n) 
begin
    if (!reset_pixel_n) begin
    	next_state         <= ST_1ST_PACK;
        pixel_data_i_p1    <= {FULL_BYTE{1'b0}};
    end
    else begin
    	next_state         <= fsm_state;
        pixel_data_i_p1    <= pixel_data_i;
    end
end

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		pixel_data_valid         <= 1'b0;
	end
	else if ((valid_depack && pixel_bits_cnt > 19'd0) || (~valid_depack && (fsm_state == ST_7TH_PACK && trigger_extra_pix))) begin
		pixel_data_valid         <= 1'b1;
	end
	else begin
		pixel_data_valid         <= 1'b0;
	end
end

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		fsm_state    <= ST_1ST_PACK;
		pixel_data   <= {PACK_BYTE{1'b0}};
	end
	else begin
        case(fsm_state)
        	ST_1ST_PACK : begin
        	    if (RAW14_r) begin
        	        pixel_data     <= {pixel_data_i[31:24], pixel_data_i[55:50], pixel_data_i[23:16], pixel_data_i[49:44], pixel_data_i[15:8], pixel_data_i[43:38], pixel_data_i[7:0], pixel_data_i[37:32]};
        	    end
        	    else begin
        	        pixel_data     <= pixel_data_i[PACK_BYTE-1:0];
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_2ND_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
        	ST_2ND_PACK : begin
        	    if (RAW14_r) begin
        	        pixel_data     <= {pixel_data_i[23:16], pixel_data_i[47:42], pixel_data_i[15:8], pixel_data_i[41:36], pixel_data_i[7:0], pixel_data_i[35:30], pixel_data_i_p1[63:56], pixel_data_i[29:24]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[47:0], pixel_data_i_p1[FULL_BYTE-1:56]};
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_3RD_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
        	ST_3RD_PACK : begin
        	    if (RAW14_r) begin
        	        pixel_data     <= {pixel_data_i[15:8], pixel_data_i[39:34], pixel_data_i[7:0], pixel_data_i[33:28], pixel_data_i_p1[63:56], pixel_data_i[27:22], pixel_data_i_p1[55:48], pixel_data_i[21:16]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[39:0], pixel_data_i_p1[FULL_BYTE-1:48]};
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_4TH_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
        	ST_4TH_PACK : begin
        	    if (RAW14_r) begin   
        	        pixel_data     <= {pixel_data_i[7:0], pixel_data_i[31:26], pixel_data_i_p1[63:56], pixel_data_i[25:20], pixel_data_i_p1[55:48], pixel_data_i[19:14], pixel_data_i_p1[47:40], pixel_data_i[13:8]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[31:0], pixel_data_i_p1[FULL_BYTE-1:40]};
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_5TH_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
            
        	ST_5TH_PACK : begin
        	    if (RAW14_r) begin
        	        pixel_data     <= {pixel_data_i_p1[63:56], pixel_data_i[23:18], pixel_data_i_p1[55:48], pixel_data_i[17:12], pixel_data_i_p1[47:40], pixel_data_i[11:6], pixel_data_i_p1[39:32], pixel_data_i[5:0]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[23:0], pixel_data_i_p1[FULL_BYTE-1:32]};
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_6TH_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
        	ST_6TH_PACK : begin
        	    if (RAW14_r) begin
        	        pixel_data     <= {pixel_data_i_p1[55:48], pixel_data_i[15:10], pixel_data_i_p1[47:40], pixel_data_i[9:4], pixel_data_i_p1[39:32], pixel_data_i[3:0], pixel_data_i_p1[63:62], pixel_data_i_p1[31:24], pixel_data_i_p1[61:56]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[15:0], pixel_data_i_p1[FULL_BYTE-1:24]};
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_7TH_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
        	ST_7TH_PACK : begin
        	    if (RAW14_r) begin
        	        pixel_data     <= {pixel_data_i_p1[47:40], pixel_data_i[7:2], pixel_data_i_p1[39:32], pixel_data_i[1:0], pixel_data_i_p1[63:60], pixel_data_i_p1[31:24], pixel_data_i_p1[59:54], pixel_data_i_p1[23:16], pixel_data_i_p1[53:48]};
        	    end
        	    else begin
        	        pixel_data     <= {pixel_data_i[7:0], pixel_data_i_p1[FULL_BYTE-1:16]};
        	    end
        	    
        	    if (valid_depack) begin
                    fsm_state    <= ST_8TH_PACK;
                end	
        	    else if (pixel_bits_cnt == 0) begin
        	    	fsm_state    <= ST_1ST_PACK;
                end
            end
            
        	ST_8TH_PACK : begin
        	    if (RAW14_r) begin
        	        pixel_data     <= {pixel_data_i_p1[39:32], pixel_data_i[63:58], pixel_data_i_p1[31:24], pixel_data_i_p1[57:52], pixel_data_i_p1[23:16], pixel_data_i_p1[51:46], pixel_data_i_p1[15:8], pixel_data_i_p1[45:40]};
        	    end
        	    else begin
        	        pixel_data     <= pixel_data_i_p1[FULL_BYTE-1:8];
        	    end
        	    
                fsm_state    <= ST_1ST_PACK;
            end
            
            default : begin 
                fsm_state    <= ST_1ST_PACK; 
                pixel_data <= {PACK_BYTE{1'b0}};
            end
        endcase
    end
end

endmodule


// synopsys translate_off
`timescale 1 ns / 1 ps													
// synopsys translate_on

module `IP_MODULE_NAME(efx_csi2_depack64bit) (
    input               clk_pixel,
    input               reset_pixel_n,
    input  logic        RGB555_r,
    input  logic        RGB444_r,
    input  logic        YUV_420_8_r,
    input  logic        odd_line,
    input  logic [63:0] pixel_data_i,
    output logic        fifo_read,
    output logic [63:0] pixel_data_o,
    output logic        pixel_data_valid,
    input  logic        valid_depack
);

localparam [1:0] ST_IDLE     = 2'b00;
localparam [1:0] ST_1ST_PACK = 2'b01;

localparam FULL_BYTE = 64;

assign fifo_read = valid_depack;

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		pixel_data_valid         <= 1'b0;
	end
	else begin
		pixel_data_valid         <= valid_depack;
	end
end

always @(posedge clk_pixel or negedge reset_pixel_n)
begin
    if (~reset_pixel_n) begin
		pixel_data_o <= {FULL_BYTE{1'b0}};
	end
	else if (valid_depack) begin
		if (RGB555_r) begin  // 1'b0 is padded to LSB of 4 green color pixels
	        pixel_data_o     <= {4'd0, pixel_data_i[63:59], pixel_data_i[58:54], pixel_data_i[52:48],
	                            pixel_data_i[47:43], pixel_data_i[42:38], pixel_data_i[36:32],
	                             pixel_data_i[31:27], pixel_data_i[26:22], pixel_data_i[20:16],
	                              pixel_data_i[15:11], pixel_data_i[10:6], pixel_data_i[4:0]};
	    end
	    else if (RGB444_r) begin  //1'b1 is padded to LSB of 4 blue color pixels, 2'b10 is padded to LSB of 4 green color pixels, 1'b1 is padded to LSB of 4 red color pixels
	        pixel_data_o     <= {16'd0, pixel_data_i[63:60], pixel_data_i[58:55], pixel_data_i[52:49], 
	                            pixel_data_i[47:44], pixel_data_i[42:39], pixel_data_i[36:33], 
	                             pixel_data_i[31:28], pixel_data_i[26:23], pixel_data_i[20:17], 
	                              pixel_data_i[15:12], pixel_data_i[10:7], pixel_data_i[4:1]};
	    end
	    else begin
	        pixel_data_o     <= pixel_data_i;
	    end
	end
end

endmodule


// synopsys translate_off
`timescale 1 ns / 1 ps													
// synopsys translate_on

module `IP_MODULE_NAME(efx_csi2_depacketizer) #(
    parameter ENABLE_VCX = 0,
	parameter FRAME_MODE = "GENERIC",    //1-ACCURATE, 0-GENERIC
    parameter NUM_DATA_LANE = 1
)(
    input  logic                            clk_byte_HS,
    input  logic                            reset_byte_HS_n,
    input  logic                            RxStopState,
    input  logic [NUM_DATA_LANE-1:0][7:0]   fifo_rddata_o,
    input  logic [NUM_DATA_LANE-1:0]        fifo_empty,
    output logic [NUM_DATA_LANE-1:0]        fifo_read,
    //to CSR register
    output logic [1:0]                      vc,
    output logic [1:0]                      vcx,
    output logic [5:0]                      datatype,
    output logic [15:0]                     word_count,
    output logic [3:0]                      actual_pixel_count,
    output logic                            ecc_1bit_error,
    output logic                            ecc_2bit_error,
    output logic                            frame_sync_vc0_error,
    output logic                            frame_sync_vc1_error,
    output logic                            frame_sync_vc2_error,
    output logic                            frame_sync_vc3_error,
    output logic                            line_sync_vc0_error,
    output logic                            line_sync_vc1_error,
    output logic                            line_sync_vc2_error,
    output logic                            line_sync_vc3_error,
    output logic                            crc_error,
    output logic                            undersize_pkt_error,
    
    output logic [15:0]                     hsync_vc,
    output logic [15:0]                     vsync_vc,
    output logic [63:0]                     pkt_data,
    output logic                            valid_pkt_data,
    output logic                            odd_line,
    output logic                            RAW6_r,
    output logic                            RAW7_r,
    output logic                            RAW8_r,
    output logic                            RAW10_r,
    output logic                            RAW12_r,
    output logic                            RAW14_r,
    output logic                            RAW20_r,    
    output logic                            RGB444_r,
    output logic                            RGB555_r,
    output logic                            RGB565_r,
    output logic                            RGB888_r,
    output logic                            YUV_422_8_r,
    output logic                            YUV_422_10_r,
    output logic                            YUV_420_8_legacy_r,
    output logic                            YUV_420_8_r,
    output logic                            YUV_420_10_r,
    output logic                            gen_long_pkt_r,
    output logic                            embed_8bit_nonvideo_r,
    output logic                            user_define_8bit_r
);

logic non_support_pkt;
logic trigger_extra_byte, trigger_extra_byte_reg, trigger_crc_din;
logic [2:0] next_state, current_state;
logic [2:0] cnt;
logic [15:0] data_cnt, extra_data_byte;
logic [31:0] pkt_header;
logic [2:0] last_packet_wc;
logic [15:0] pkt_crc16, crc;
logic FS, FE, LS, LE, gen_long_pkt, user_define_8bit, embed_8bit_nonvideo;
logic crc8_en, crc16_en, crc24_en, crc32_en, crc40_en, crc48_en, crc56_en, crc64_en;
logic YUV_422_8, YUV_422_10, RGB444, RGB555, RGB565, RGB888;
logic RAW6, RAW7, RAW8, RAW10, RAW12, RAW14, RAW20;
logic YUV_420_8_legacy, YUV_420_8, YUV_420_10;
logic short_pkt_type, vld_pkt_header, state_idle, start_depack, vld_pkt_header_reg;
logic check_ecc, check_crc, clr_crc, reset_cnt, crc_data_in_valid;
logic [15:0] fs_vc0_datafield, fe_vc0_datafield, ls_vc0_datafield, le_vc0_datafield;
logic [15:0] fs_vc1_datafield, fe_vc1_datafield, ls_vc1_datafield, le_vc1_datafield;
logic [15:0] fs_vc2_datafield, fe_vc2_datafield, ls_vc2_datafield, le_vc2_datafield;
logic [15:0] fs_vc3_datafield, fe_vc3_datafield, ls_vc3_datafield, le_vc3_datafield;
logic [7:0] fifo_rddata_0, fifo_rddata_1, fifo_rddata_2, fifo_rddata_3;
logic [7:0] fifo_rddata_4, fifo_rddata_5, fifo_rddata_6, fifo_rddata_7;
logic [7:0] fifo_rddata_0_reg, fifo_rddata_1_reg, fifo_rddata_2_reg, fifo_rddata_3_reg;
logic [7:0] fifo_rddata_4_reg, fifo_rddata_5_reg, fifo_rddata_6_reg, fifo_rddata_7_reg;

localparam ST_IDLE      = 3'd0;
localparam ST_PH        = 3'd1;
localparam ST_DATA      = 3'd2;
localparam ST_PF        = 3'd3;
localparam ST_CHECK_CRC = 3'd4;
localparam ST_FLUSH     = 3'd5;

assign clr_crc = (current_state == ST_IDLE);
assign state_idle = (current_state == ST_IDLE);
assign start_depack = (current_state == ST_IDLE && next_state == ST_PH);

generate
if (NUM_DATA_LANE == 1) begin
assign valid_pkt_data = ((current_state == ST_DATA) && ((cnt == 3'd7) || (data_cnt <= 16'd1)));
assign crc_data_in_valid = (next_state == ST_DATA);
assign check_crc = (current_state == ST_CHECK_CRC);
assign fifo_rddata_0 = fifo_rddata_o[0][7:0];
assign trigger_extra_byte = ((current_state == ST_DATA) && (data_cnt > 1) && (data_cnt <= 8)  && (cnt == 3'd7));

end
else if (NUM_DATA_LANE == 2) begin
assign valid_pkt_data = ((current_state == ST_DATA) && ((cnt == 3'd3) || (data_cnt <= 16'd2)));
assign crc_data_in_valid = (next_state == ST_DATA);
assign check_crc = (current_state == ST_CHECK_CRC);
assign fifo_rddata_0 = fifo_rddata_o[0][7:0];
assign fifo_rddata_1 = fifo_rddata_o[1][7:0];
assign fifo_rddata_2 = 8'h0;
assign fifo_rddata_3 = 8'h0;
assign fifo_rddata_4 = 8'h0;
assign fifo_rddata_5 = 8'h0;
assign fifo_rddata_6 = 8'h0;
assign fifo_rddata_7 = 8'h0;
assign trigger_extra_byte = ((current_state == ST_DATA) && (data_cnt > 2) && (data_cnt <= 9)  && (cnt == 3'd3));

end
else if (NUM_DATA_LANE == 4) begin
assign valid_pkt_data = ((current_state == ST_DATA) && ((cnt == 3'd1) || (data_cnt <= 16'd4)));
assign crc_data_in_valid = (next_state == ST_DATA);
assign check_crc = (current_state == ST_CHECK_CRC);
assign fifo_rddata_0 = fifo_rddata_o[0][7:0];
assign fifo_rddata_1 = fifo_rddata_o[1][7:0];
assign fifo_rddata_2 = fifo_rddata_o[2][7:0];
assign fifo_rddata_3 = fifo_rddata_o[3][7:0];
assign fifo_rddata_4 = 8'h0;
assign fifo_rddata_5 = 8'h0;
assign fifo_rddata_6 = 8'h0;
assign fifo_rddata_7 = 8'h0;
assign trigger_extra_byte = ((current_state == ST_DATA) && (data_cnt > 4) && (data_cnt <= 11) && (cnt == 3'd1));

end
else if (NUM_DATA_LANE == 8) begin
assign crc_data_in_valid = (current_state == ST_DATA);
assign check_crc = (current_state == ST_CHECK_CRC);
assign fifo_rddata_0 = fifo_rddata_o[0][7:0];
assign fifo_rddata_1 = fifo_rddata_o[1][7:0];
assign fifo_rddata_2 = fifo_rddata_o[2][7:0];
assign fifo_rddata_3 = fifo_rddata_o[3][7:0];
assign fifo_rddata_4 = fifo_rddata_o[4][7:0];
assign fifo_rddata_5 = fifo_rddata_o[5][7:0];
assign fifo_rddata_6 = fifo_rddata_o[6][7:0];
assign fifo_rddata_7 = fifo_rddata_o[7][7:0];
assign trigger_extra_byte = 0;  //not applicable to 8lane
assign trigger_crc_din = (current_state == ST_PH && next_state == ST_DATA);

always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        fifo_rddata_0_reg <= 8'h0;
        fifo_rddata_1_reg <= 8'h0;
        fifo_rddata_2_reg <= 8'h0;
        fifo_rddata_3_reg <= 8'h0;
        fifo_rddata_4_reg <= 8'h0;
        fifo_rddata_5_reg <= 8'h0;
        fifo_rddata_6_reg <= 8'h0;
        fifo_rddata_7_reg <= 8'h0;
        valid_pkt_data  <= 1'b0;
	end
	else begin
        fifo_rddata_0_reg <= fifo_rddata_0;
        fifo_rddata_1_reg <= fifo_rddata_1;
        fifo_rddata_2_reg <= fifo_rddata_2;
        fifo_rddata_3_reg <= fifo_rddata_3;
        fifo_rddata_4_reg <= fifo_rddata_4;
        fifo_rddata_5_reg <= fifo_rddata_5;
        fifo_rddata_6_reg <= fifo_rddata_6;
        fifo_rddata_7_reg <= fifo_rddata_7;
        valid_pkt_data  <= (current_state == ST_DATA) || (current_state == ST_PF && ((data_cnt > 16'd4) || (data_cnt == 0)));
	end
end

end
endgenerate

always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        vld_pkt_header_reg      <= 1'b0;
        odd_line               <= 1'b0;
	end
	else begin
        vld_pkt_header_reg      <= vld_pkt_header;
        
        if (vld_pkt_header && (YUV_420_8 || YUV_420_10)) begin
            odd_line               <= ~odd_line;
        end
	end
end

always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        current_state <= ST_IDLE;
	end
	else begin
        current_state <= next_state;
	end
end

always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        cnt <= 3'd0;
	end
	else if (reset_cnt) begin
        cnt <= 3'd0;
	end
	else begin
        cnt <= cnt + 3'd1;
	end
end

always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
    if(!reset_byte_HS_n)begin
        data_cnt <= 16'd0;
    end
    else if (short_pkt_type) begin
        data_cnt <= 16'd0;
    end
    else if (current_state == ST_DATA && data_cnt >= NUM_DATA_LANE) begin
        data_cnt <= data_cnt - NUM_DATA_LANE;
    end
    else if (current_state == ST_PH) begin
        if (NUM_DATA_LANE == 8) begin
            data_cnt <= word_count - 16'd4;
        end
        else begin
            data_cnt <= word_count;	
        end
    end
    else if (current_state == ST_FLUSH) begin
        data_cnt <= 16'd0;
    end
end

always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        trigger_extra_byte_reg <= 1'b0;
	end
	else if (trigger_extra_byte) begin
	    trigger_extra_byte_reg <= 1'b1;
	end
	else if (start_depack) begin
	    trigger_extra_byte_reg <= 1'b0;;
	end
end

generate if (FRAME_MODE == "ACCURATE") begin
    always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
    begin
        if(!reset_byte_HS_n) begin
            hsync_vc[0]         <= 1'b0;
            hsync_vc[1]         <= 1'b0;
            hsync_vc[2]         <= 1'b0;
            hsync_vc[3]         <= 1'b0;
            vsync_vc[0]         <= 1'b0;
            vsync_vc[1]         <= 1'b0;
            vsync_vc[2]         <= 1'b0;
            vsync_vc[3]         <= 1'b0;
            fs_vc0_datafield    <= 16'd0;
            fe_vc0_datafield    <= 16'd0;
            ls_vc0_datafield    <= 16'd0;
            le_vc0_datafield    <= 16'd0;
            fs_vc1_datafield    <= 16'd0;
            fe_vc1_datafield    <= 16'd0;
            ls_vc1_datafield    <= 16'd0;
            le_vc1_datafield    <= 16'd0;
            fs_vc2_datafield    <= 16'd0;
            fe_vc2_datafield    <= 16'd0;
            ls_vc2_datafield    <= 16'd0;
            le_vc2_datafield    <= 16'd0;
            fs_vc3_datafield    <= 16'd0;
            fe_vc3_datafield    <= 16'd0;
            ls_vc3_datafield    <= 16'd0;
            le_vc3_datafield    <= 16'd0;
        end
        else if (vld_pkt_header && vcx == 2'b00 && vc == 2'b00) begin
        	if (LS) begin
                hsync_vc[0]      <= 1'b1;
                ls_vc0_datafield <= word_count;
        	end
        	else if (LE) begin
                hsync_vc[0]      <= 1'b0;
                le_vc0_datafield <= word_count;
        	end
        	
        	if (FS) begin
                vsync_vc[0]        <= 1'b1;
                fs_vc0_datafield <= word_count;
        	end
