// Synchronization error
//1)Line/frame start to same channel without Line/frame end //2)Line/frame end to same channel without Line/frame start
//3)Line/frame start datafield not the same as Line/frame end datafield
always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
    if(!reset_byte_HS_n) begin
        frame_sync_vc0_error   <= 1'b0;
        frame_sync_vc1_error   <= 1'b0;
        frame_sync_vc2_error   <= 1'b0;
        frame_sync_vc3_error   <= 1'b0;
        line_sync_vc0_error    <= 1'b0;
        line_sync_vc1_error    <= 1'b0;
        line_sync_vc2_error    <= 1'b0;
        line_sync_vc3_error    <= 1'b0;
    end
    else if (vc == 2'b00) begin
    	if (LS || LE) begin
    	    if ((hsync_vc[0] && LS) || (LE && (word_count != ls_vc0_datafield)) || (!hsync_vc[0] && LE)) begin 
    	        line_sync_vc0_error    <= 1'b1;
    	    end
    	    else begin
    	        line_sync_vc0_error    <= 1'b0;
    	    end
    	end
    	
