    	    YUV_422_10_r           <= 1'b1;
    	end
    	if (YUV_420_8_legacy) begin
    	    YUV_420_8_legacy_r     <= 1'b1;
    	end
    	if (YUV_420_8) begin
    	    YUV_420_8_r            <= 1'b1;
    	end
    	if (YUV_420_10) begin
    	    YUV_420_10_r           <= 1'b1;
    	end
    	if (user_define_8bit) begin
    	    user_define_8bit_r    <= 1'b1;
    	end
    	if (gen_long_pkt) begin
    	    gen_long_pkt_r        <= 1'b1;
    	end
    	if (embed_8bit_nonvideo) begin
    	    embed_8bit_nonvideo_r  <= 1'b1;
    	end
    end
    else if (start_depack) begin  
        RAW6_r              <= 1'b0;
        RAW7_r              <= 1'b0;
        RAW8_r              <= 1'b0;
        RAW10_r             <= 1'b0;
        RAW12_r             <= 1'b0;
        RAW14_r             <= 1'b0;
        RAW20_r             <= 1'b0;
        RGB444_r            <= 1'b0;
        RGB555_r            <= 1'b0;
        RGB565_r            <= 1'b0;
        RGB888_r            <= 1'b0;
        YUV_422_8_r         <= 1'b0;
        YUV_422_10_r        <= 1'b0;
        YUV_420_8_legacy_r  <= 1'b0;
        YUV_420_8_r         <= 1'b0;
        YUV_420_10_r        <= 1'b0;
        gen_long_pkt_r      <= 1'b0;
        embed_8bit_nonvideo_r<= 1'b0; 
        user_define_8bit_r  <= 1'b0;
    end
end

always @* begin
    FS = 1'b0;
    FE = 1'b0;
    LS = 1'b0;
    LE = 1'b0;
    gen_long_pkt = 1'b0;
    embed_8bit_nonvideo = 1'b0;
    YUV_422_8 = 1'b0;
    YUV_422_10 = 1'b0;
    YUV_420_8 = 1'b0;
    YUV_420_8_legacy = 1'b0;
    YUV_420_10 = 1'b0;
    RGB444 = 1'b0;
    RGB555 = 1'b0;
    RGB565 = 1'b0;
    RGB888 = 1'b0;
    RAW6 = 1'b0;
    RAW7 = 1'b0;
    RAW8 = 1'b0;
    RAW10 = 1'b0;
    RAW12 = 1'b0;
    RAW14 = 1'b0;
    RAW20 = 1'b0;
    user_define_8bit = 1'b0;
    non_support_pkt = 1'b0;
    short_pkt_type = 1'b0;
    
    if (vld_pkt_header) begin
        case(datatype)
            6'h0 : begin FS = 1'b1; short_pkt_type = 1'b1; end
            6'h1 : begin FE = 1'b1; short_pkt_type = 1'b1; end
            6'h2 : begin LS = 1'b1; short_pkt_type = 1'b1; end
            6'h3 : begin LE = 1'b1; short_pkt_type = 1'b1; end
            6'h08,6'h09,6'h0A,6'h0B,6'h0C,6'h0D,6'h0E,6'h0F : begin short_pkt_type = 1'b1; end  // generic short packet
            6'h10, 6'h11 : begin short_pkt_type = 1'b1; end    // NULL & Blank data type, packet data is ignored
            6'h12 : begin embed_8bit_nonvideo = 1'b1; end
            6'h13,6'h14,6'h15,6'h16 : gen_long_pkt = 1'b1; 
            6'h18, 6'h1C : YUV_420_8 = 1'b1;
            6'h19, 6'h1D : YUV_420_10 = 1'b1;
            6'h1A : YUV_420_8_legacy = 1'b1;
            6'h1E : YUV_422_8 = 1'b1;
            6'h1F : YUV_422_10 = 1'b1;
            6'h20 : RGB444 = 1'b1;
            6'h21 : RGB555 = 1'b1;
            6'h22 : RGB565 = 1'b1;
            6'h24 : RGB888 = 1'b1;
            6'h28 : RAW6 = 1'b1;
            6'h29 : RAW7 = 1'b1;
            6'h2A : RAW8 = 1'b1;
            6'h2B : RAW10 = 1'b1;
            6'h2C : RAW12 = 1'b1;
            6'h2D : RAW14 = 1'b1;
            6'h2F : RAW20 = 1'b1;
            6'h30,6'h31,6'h32,6'h33,6'h34,6'h35,6'h36,6'h37: user_define_8bit = 1'b1;
        default : non_support_pkt = 1'b1;
        endcase
    end
end

always @* begin
    reset_cnt   = 1'b0;
    check_ecc   = 1'b0;
    fifo_read   = {NUM_DATA_LANE{1'b0}};
    next_state  = current_state;
    case(current_state)
    	ST_IDLE : begin
    	    reset_cnt   = 1'b1;
    	    if (NUM_DATA_LANE == 8) begin
                if (fifo_empty[3:0] == 4'b0000) begin  //packet Header is 32-bit
                	fifo_read   = {NUM_DATA_LANE{1'b0}};
                    next_state    = ST_PH;
                end
                else begin
                	fifo_read   = {NUM_DATA_LANE{1'b0}};
                    next_state    = ST_IDLE;
                end
            end
            else begin
                if (fifo_empty == {NUM_DATA_LANE{1'b0}}) begin
                	fifo_read     = {NUM_DATA_LANE{1'b1}};
                    next_state    = ST_PH;
                end
                else begin
                	fifo_read   = {NUM_DATA_LANE{1'b0}};
                    next_state    = ST_IDLE;
                end
            end
    	end
    	
    	ST_PH : begin
    	    if (((NUM_DATA_LANE == 4) && (cnt == 3'd0)) || (NUM_DATA_LANE == 1 && (cnt == 3'd3)) || (NUM_DATA_LANE == 2 && (cnt == 3'd1))) begin
    	        check_ecc     = 1'b1;
    	        fifo_read     = {NUM_DATA_LANE{1'b0}};
    	        reset_cnt     = 1'b0;
    	        next_state    = ST_PH;
    	    end
    	    else if (NUM_DATA_LANE == 8 && (cnt == 3'd0)) begin
    	        check_ecc     = 1'b1;
    	        fifo_read     = {NUM_DATA_LANE{1'b0}};
    	        reset_cnt     = 1'b0;
    	        next_state    = ST_PH;
    	    end
    	    else if (((NUM_DATA_LANE == 4 || NUM_DATA_LANE == 8) && (cnt == 3'd1)) || ((NUM_DATA_LANE == 1 && (cnt == 3'd4)) || (NUM_DATA_LANE == 2 && (cnt == 3'd2)))) begin
    	        check_ecc   = 1'b0;
    	        fifo_read     = {NUM_DATA_LANE{1'b1}};
    	    	if (vld_pkt_header) begin
    	            reset_cnt     = 1'b1;
    	            if (short_pkt_type) begin
                        next_state    = ST_FLUSH;
                    end
                    else if (non_support_pkt) begin
                        next_state    = ST_FLUSH;
                    end
                    else begin
                        next_state    = ST_DATA;
                    end
                end
                else begin
    	            reset_cnt     = 1'b1;
                    next_state    = ST_FLUSH;	
                end
    	    end
    	    else if (RxStopState) begin   // LP stop unexpectedly
                fifo_read     = {NUM_DATA_LANE{1'b1}};
    	        check_ecc     = 1'b0;
    	    	reset_cnt     = 1'b0;
    	        next_state    = ST_FLUSH;
    	    end
    	    else begin
    	        fifo_read     = {NUM_DATA_LANE{1'b1}};
    	        check_ecc     = 1'b0;
    	    	reset_cnt     = 1'b0;
    	        next_state    = ST_PH;
    	    end
    	end
    	
    	ST_DATA : begin
    	    if ((NUM_DATA_LANE == 1 && data_cnt <= 16'h1) || (NUM_DATA_LANE == 2 && data_cnt <= 16'h2) 
    	       || (NUM_DATA_LANE == 4 && data_cnt <= 16'h4)) begin    // when data_cnt = 1, it is the last packet data byte
    	       fifo_read     = {NUM_DATA_LANE{1'b0}}; 
    	       next_state    = ST_PF;
    	    end
    	    else if (NUM_DATA_LANE == 8 && data_cnt <= 16'h8) begin
                fifo_read     = {NUM_DATA_LANE{1'b1}};
    	        next_state    = ST_PF;
    	    end
    	    else if (RxStopState) begin   // LP stop unexpectedly
                fifo_read     = {NUM_DATA_LANE{1'b1}};
    	        next_state    = ST_FLUSH;
    	    end
    	    else begin
    	        fifo_read     = {NUM_DATA_LANE{1'b1}};
    	        next_state    = ST_DATA;
    	    end
    	    
    	    if ((NUM_DATA_LANE == 1 && (cnt == 3'd7 || data_cnt == 16'h1)) || (NUM_DATA_LANE == 2 && (cnt == 3'd3 || data_cnt == 16'h2)) || (NUM_DATA_LANE == 4 && (cnt == 3'd1 || data_cnt == 16'h4)) || (NUM_DATA_LANE == 8)) begin
    	        reset_cnt    = 1'b1;
    	    end
    	    else begin
    	        reset_cnt    = 1'b0;
    	    end
    	end
    	
    	ST_PF : begin
    	    if (NUM_DATA_LANE == 1) begin
    	        fifo_read  = {NUM_DATA_LANE{1'b1}};  //1st CRC byte in lane 0 and 2nd CRC byte in lane 0 of next clock
    	        if (cnt == 3'd1) begin
    	            reset_cnt  = 1'b1;
    	            next_state = ST_CHECK_CRC;
    	        end
    	        else begin
    	            reset_cnt  = 1'b0;
    	            next_state = ST_PF;
    	        end
    	    end
    	    else if (NUM_DATA_LANE == 2) begin      //1st CRC byte in lane 0 and 2nd CRC byte in lane 1
    	        reset_cnt  = 1'b1;
    	        fifo_read  = {NUM_DATA_LANE{1'b1}};
    	        next_state = ST_CHECK_CRC;
    	    end
    	    else if (NUM_DATA_LANE == 4) begin
    	        reset_cnt  = 1'b1;
    	        fifo_read  = {NUM_DATA_LANE{1'b1}};  //1st CRC byte in lane 0 and 2nd CRC byte in lane 1, lane 2 & 3 is filler byte
    	        next_state = ST_CHECK_CRC;
    	    end
    	    else if (NUM_DATA_LANE == 8) begin
    	        reset_cnt  = 1'b1;
    	        fifo_read  = {NUM_DATA_LANE{1'b1}};  //1st CRC byte in lane 0 and 2nd CRC byte in lane 1, lane 2&3&4&5&6&7 is filler byte
    	        next_state = ST_CHECK_CRC;
    	    end
    	    else if (RxStopState) begin   // LP stop unexpectedly
    	    	reset_cnt     = 1'b1;
                fifo_read     = {NUM_DATA_LANE{1'b1}};
    	        next_state    = ST_FLUSH;
    	    end
    	end
    	
    	ST_CHECK_CRC : begin
            reset_cnt     = 1'b1;
    	    fifo_read     = {NUM_DATA_LANE{1'b0}};
    	    next_state    = ST_FLUSH;
        end
    	
    	ST_FLUSH : begin
    	    if (&fifo_empty == 1'b1) begin
    	    	reset_cnt     = 1'b1;
    	    	fifo_read     = {NUM_DATA_LANE{1'b0}};
    	        next_state    = ST_IDLE;
    	    end
    	    else begin  // flush out all the packet in the line FIFO
    	    	reset_cnt     = 1'b1;
    	    	fifo_read     = {NUM_DATA_LANE{1'b1}};
    	        next_state    = ST_FLUSH;
    	    end
    	end
    	
    	default :    begin
    	    reset_cnt   = 1'b0;
    	    check_ecc   = 1'b0;
            fifo_read   = {8{1'b0}};
    	    next_state  = ST_IDLE;
    	end
    endcase
end

always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        pkt_data     <= 64'd0;
        pkt_header   <= 32'd0;
        pkt_crc16    <= 16'd0;
	end
	else begin
        case(current_state)
            ST_IDLE : begin
                if (NUM_DATA_LANE == 1) begin
                    pkt_header    <= {fifo_rddata_0[7:0], pkt_header[31:8]};
                end
                else if (NUM_DATA_LANE == 2) begin
                    pkt_header    <= {fifo_rddata_1[7:0], fifo_rddata_0[7:0], pkt_header[31:16]};
                end
                else begin
                    pkt_header    <= {fifo_rddata_3[7:0], fifo_rddata_2[7:0], fifo_rddata_1[7:0], fifo_rddata_0[7:0]};
                end
            end
            
            ST_PH : begin
                if (NUM_DATA_LANE == 1) begin
                    pkt_header    <= {fifo_rddata_0[7:0], pkt_header[31:8]};
                    pkt_data      <= {fifo_rddata_0, pkt_data[63:8]};
                end
                else if (NUM_DATA_LANE == 2) begin
                    pkt_header    <= {fifo_rddata_1[7:0], fifo_rddata_0[7:0], pkt_header[31:16]};
                    pkt_data      <= {fifo_rddata_1, fifo_rddata_0, pkt_data[63:16]};
                end
                else if (NUM_DATA_LANE == 4) begin
                    pkt_header    <= {fifo_rddata_3[7:0], fifo_rddata_2[7:0], fifo_rddata_1[7:0], fifo_rddata_0[7:0]};
                    pkt_data      <= {fifo_rddata_3, fifo_rddata_2, fifo_rddata_1, fifo_rddata_0, pkt_data[63:32]};
                end
                else begin
                    pkt_header    <= {fifo_rddata_3[7:0], fifo_rddata_2[7:0], fifo_rddata_1[7:0], fifo_rddata_0[7:0]};
                    pkt_data      <= {fifo_rddata_3, fifo_rddata_2, fifo_rddata_1, fifo_rddata_0, fifo_rddata_7_reg, fifo_rddata_6_reg, fifo_rddata_5_reg, fifo_rddata_4_reg};  //swap with older 4MSB
                end
            end
            
            ST_DATA : begin  
                if (NUM_DATA_LANE == 1) begin
                    if (trigger_extra_byte || trigger_extra_byte_reg) begin
                        case (cnt)
                        	3'd7 : pkt_data    <= {pkt_data[63:8],  fifo_rddata_0};
    	    	            3'd0 : pkt_data    <= {pkt_data[63:16], fifo_rddata_0, pkt_data[7:0]};
    	    	            3'd1 : pkt_data    <= {pkt_data[63:24], fifo_rddata_0, pkt_data[15:0]};
    	    	            3'd2 : pkt_data    <= {pkt_data[63:32], fifo_rddata_0, pkt_data[23:0]};
    	    	            3'd3 : pkt_data    <= {pkt_data[63:40], fifo_rddata_0, pkt_data[31:0]};
    	    	            3'd4 : pkt_data    <= {pkt_data[63:48], fifo_rddata_0, pkt_data[39:0]};
    	    	            3'd5 : pkt_data    <= {pkt_data[63:56], fifo_rddata_0, pkt_data[47:0]};
    	    	            3'd6 : pkt_data    <= {fifo_rddata_0,   pkt_data[55:0]};
    	    	            default : pkt_data  <= {64{1'b0}};
                        endcase
                	end
                	else begin
                        pkt_data    <= {fifo_rddata_0, pkt_data[63:8]};
                    end
                    
                    pkt_crc16   <= {fifo_rddata_0, pkt_crc16[15:8]};
                end
                else if (NUM_DATA_LANE == 2) begin
                	if (trigger_extra_byte || trigger_extra_byte_reg) begin
                        case (cnt)
                        	3'd3 : pkt_data    <= {pkt_data[63:16], fifo_rddata_1, fifo_rddata_0};
    	    	            3'd0 : pkt_data    <= {pkt_data[63:32], fifo_rddata_1, fifo_rddata_0, pkt_data[15:0]};
    	    	            3'd1 : pkt_data    <= {pkt_data[63:48], fifo_rddata_1, fifo_rddata_0, pkt_data[31:0]};
    	    	            3'd2 : pkt_data    <= {fifo_rddata_1, fifo_rddata_0, pkt_data[47:0]};
    	    	            default : pkt_data  <= {64{1'b0}};
                        endcase
                	end
                	else begin
                        pkt_data    <= {fifo_rddata_1, fifo_rddata_0, pkt_data[63:16]};
                    end
                    
                         if (data_cnt-2 == 16'd0) pkt_crc16 <= {fifo_rddata_1, fifo_rddata_0};
                    else if (data_cnt-2 == 16'd1) pkt_crc16 <= {fifo_rddata_1, pkt_crc16[15:8]};
                    
                end
                else if (NUM_DATA_LANE == 4) begin
                	if (trigger_extra_byte || trigger_extra_byte_reg) begin
                        case (cnt)
    	    	            3'd1 : pkt_data    <= {32'd0, fifo_rddata_3, fifo_rddata_2, fifo_rddata_1, fifo_rddata_0};
    	    	            3'd0 : pkt_data    <= {fifo_rddata_3, fifo_rddata_2, fifo_rddata_1, fifo_rddata_0, pkt_data[31:0]};
    	    	            default : pkt_data  <= {64{1'b0}};
    	    	        endcase
                	end
                	else begin
                        pkt_data    <= {fifo_rddata_3, fifo_rddata_2, fifo_rddata_1, fifo_rddata_0, pkt_data[63:32]};
                    end
                    
                         if (data_cnt-4 == 16'd0) pkt_crc16 <= {fifo_rddata_1, fifo_rddata_0};
                    else if (data_cnt-4 == 16'd1) pkt_crc16 <= {fifo_rddata_2, fifo_rddata_1};
                    else if (data_cnt-4 == 16'd2) pkt_crc16 <= {fifo_rddata_3, fifo_rddata_2};
                    else if (data_cnt-4 == 16'd3) pkt_crc16 <= {fifo_rddata_3, pkt_crc16[15:8]};
                end
                else begin
                    pkt_data    <= {fifo_rddata_3, fifo_rddata_2, fifo_rddata_1, fifo_rddata_0, fifo_rddata_7_reg, fifo_rddata_6_reg, fifo_rddata_5_reg, fifo_rddata_4_reg};
                end
            end
            
            ST_PF : begin   
                if (NUM_DATA_LANE == 1) begin
                    pkt_crc16   <= {fifo_rddata_0, pkt_crc16[15:8]};
                end
                
                if (NUM_DATA_LANE == 2) begin
                    if (data_cnt == 16'd1) pkt_crc16 <= {fifo_rddata_0, pkt_crc16[15:8]};
                end
                
                if (NUM_DATA_LANE == 4) begin
                    if (data_cnt == 16'd3) pkt_crc16 <= {fifo_rddata_0, pkt_crc16[15:8]};
                end
                
                if (NUM_DATA_LANE == 8) begin
                    if (data_cnt == 16'd0 || data_cnt == 16'd8) begin
                        pkt_crc16 <= {fifo_rddata_1, fifo_rddata_0};
                        pkt_data  <= {32'h0, fifo_rddata_7_reg, fifo_rddata_6_reg, fifo_rddata_5_reg, fifo_rddata_4_reg};
                    end
                    else if (data_cnt == 16'd1) begin
                        pkt_crc16 <= {fifo_rddata_2_reg, fifo_rddata_1_reg};
                    end
                    else if (data_cnt == 16'd2) begin
                        pkt_crc16 <= {fifo_rddata_3_reg, fifo_rddata_2_reg};
                    end
                    else if (data_cnt == 16'd3) begin
                        pkt_crc16 <= {fifo_rddata_4_reg, fifo_rddata_3_reg};
                    end
                    else if (data_cnt == 16'd4) begin
                        pkt_crc16 <= {fifo_rddata_5_reg, fifo_rddata_4_reg};
                    end
                    else if (data_cnt == 16'd5) begin
                        pkt_crc16 <= {fifo_rddata_6_reg, fifo_rddata_5_reg};
                        pkt_data  <= {56'h0, fifo_rddata_4_reg};
                    end
                    else if (data_cnt == 16'd6) begin
                        pkt_crc16 <= {fifo_rddata_7_reg, fifo_rddata_6_reg};
                        pkt_data  <= {48'h0, fifo_rddata_5_reg, fifo_rddata_4_reg};
                    end
                    else if (data_cnt == 16'd7) begin
                        pkt_crc16 <= {fifo_rddata_0, fifo_rddata_7_reg};
                        pkt_data  <= {40'h0, fifo_rddata_6_reg, fifo_rddata_5_reg, fifo_rddata_4_reg};
                    end
                end
            end
        endcase
	end
end

generate 
if (ENABLE_VCX) begin
`IP_MODULE_NAME(efx_csi2_ecc_check) ecc_check_inst(
    .clk_byte_HS        (clk_byte_HS),
    .reset_byte_HS_n    (reset_byte_HS_n),
    .pkt_header         ({pkt_header[31:30], pkt_header[23:0]}),
    .ecc_byte           (pkt_header[29:24]),
    .check_ecc          (check_ecc),
    .wc                 (word_count),
    .vc                 (vc),
    .vcx                (vcx), //2-bit
    .datatype           (datatype),
    .vld_pkt_header     (vld_pkt_header),
    .ecc_1bit_error     (ecc_1bit_error),
    .ecc_2bit_error     (ecc_2bit_error)
);
end
else begin
assign vcx = 2'b00;
`IP_MODULE_NAME(efx_csi2_ecc_check) ecc_check_inst(
    .clk_byte_HS        (clk_byte_HS),
    .reset_byte_HS_n    (reset_byte_HS_n),
    .pkt_header         ({2'b00, pkt_header[23:0]}),
    .ecc_byte           (pkt_header[29:24]),
    .check_ecc          (check_ecc),
    .wc                 (word_count),
    .vc                 (vc),
    .vcx                (), //2-bit
    .datatype           (datatype),
    .vld_pkt_header     (vld_pkt_header),
    .ecc_1bit_error     (ecc_1bit_error),
    .ecc_2bit_error     (ecc_2bit_error)
);
end

if (NUM_DATA_LANE == 8) begin
logic [63:0] din;
always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        crc8_en    <= 1'b0;
        crc16_en   <= 1'b0;
        crc24_en   <= 1'b0;
        crc32_en   <= 1'b0;
        crc40_en   <= 1'b0;
        crc48_en   <= 1'b0;
        crc56_en   <= 1'b0;
        crc64_en   <= 1'b0;
        din        <= 64'h0;
	end
	else begin
        if (crc_data_in_valid && (data_cnt == 16'd1)) crc8_en    <= 1'b1;
        else crc8_en    <= 1'b0;
        
        if (crc_data_in_valid && (data_cnt == 16'd2)) crc16_en    <= 1'b1;
        else crc16_en    <= 1'b0;
        
        if (crc_data_in_valid && (data_cnt == 16'd3)) crc24_en    <= 1'b1;
        else crc24_en    <= 1'b0;
        
        if ((crc_data_in_valid && (data_cnt == 16'd4)) || trigger_crc_din) crc32_en    <= 1'b1;
        else crc32_en    <= 1'b0;
        
        if (crc_data_in_valid && (data_cnt == 16'd5)) crc40_en    <= 1'b1;
        else crc40_en    <= 1'b0;
        
        if (crc_data_in_valid && (data_cnt == 16'd6)) crc48_en    <= 1'b1;
        else crc48_en    <= 1'b0;
        
        if (crc_data_in_valid && (data_cnt == 16'd7)) crc56_en    <= 1'b1;
        else crc56_en    <= 1'b0;
        
        if (crc_data_in_valid && (data_cnt >= NUM_DATA_LANE)) crc64_en    <= 1'b1;
        else crc64_en    <= 1'b0;
        
        if (trigger_crc_din) begin
            din    <= {32'h0, fifo_rddata_7, fifo_rddata_6, fifo_rddata_5, fifo_rddata_4};
        end
        else begin
            din    <= {fifo_rddata_7, fifo_rddata_6, fifo_rddata_5, fifo_rddata_4, fifo_rddata_3, fifo_rddata_2, fifo_rddata_1, fifo_rddata_0};
        end
	end
end

`IP_MODULE_NAME(efx_csi2_crc16_d64_gen) crc16_d64_gen_inst(
    .clk        (clk_byte_HS),
    .rst_n      (reset_byte_HS_n),
    .crc8_en    (crc8_en ),
    .crc16_en   (crc16_en),
    .crc24_en   (crc24_en),
    .crc32_en   (crc32_en),
    .crc40_en   (crc40_en),
    .crc48_en   (crc48_en),
    .crc56_en   (crc56_en),
    .crc64_en   (crc64_en),
    .din        (din),
    .clr_crc    (clr_crc),
    .crc        (crc)
);
end
else if (NUM_DATA_LANE == 4) begin
logic [31:0] din;
always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        crc8_en    <= 1'b0;
        crc16_en   <= 1'b0;
        crc24_en   <= 1'b0;
        crc32_en   <= 1'b0;
        din        <= 32'h0;
	end
	else begin
        if (crc_data_in_valid && ((data_cnt - 4) == 16'd1)) crc8_en    <= 1'b1;
        else crc8_en    <= 1'b0;
        
        if (crc_data_in_valid && ((data_cnt - 4) == 16'd2)) crc16_en    <= 1'b1;
        else crc16_en    <= 1'b0;
        
        if (crc_data_in_valid && ((data_cnt - 4) == 16'd3)) crc24_en    <= 1'b1;
        else crc24_en    <= 1'b0;
        
        if ((crc_data_in_valid && (data_cnt - 4 >= NUM_DATA_LANE)) || ((current_state == ST_PH) && (next_state == ST_DATA))) crc32_en    <= 1'b1;
        else crc32_en    <= 1'b0;

        din    <= {fifo_rddata_3, fifo_rddata_2, fifo_rddata_1, fifo_rddata_0};
	end
end

`IP_MODULE_NAME(efx_csi2_crc16_d32_gen) crc16_d32_gen_inst(
    .clk        (clk_byte_HS),
    .rst_n      (reset_byte_HS_n),
    .crc8_en    (crc8_en), 
    .crc16_en   (crc16_en),
    .crc24_en   (crc24_en),
    .crc32_en   (crc32_en),
    .din        (din),
    .clr_crc    (clr_crc),
    .crc        (crc)
);
end
else if (NUM_DATA_LANE == 2) begin
logic [15:0] din;
always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        crc8_en    <= 1'b0;
        crc16_en   <= 1'b0;
        din        <= 16'h0;
	end
	else begin
        if (crc_data_in_valid && ((data_cnt - 2) == 16'd1)) crc8_en    <= 1'b1;
        else crc8_en    <= 1'b0;
        
        if ((crc_data_in_valid && ((data_cnt - 2) >= NUM_DATA_LANE)) || ((current_state == ST_PH) && (next_state == ST_DATA))) crc16_en    <= 1'b1;
        else crc16_en    <= 1'b0;

        din    <= {fifo_rddata_1, fifo_rddata_0};
	end
end

`IP_MODULE_NAME(efx_csi2_crc16_d16_gen) crc16_d16_gen_inst(
    .clk        (clk_byte_HS),
    .rst_n      (reset_byte_HS_n),
    .crc8_en    (crc8_en), 
    .crc16_en   (crc16_en),
    .din        (din),
    .clr_crc    (clr_crc),
    .crc        (crc)
);
end
else begin
logic [7:0] din;
always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        crc8_en    <= 1'b0;
        din        <= 8'h0;
	end
	else begin
        if (crc_data_in_valid) crc8_en    <= 1'b1;
        else crc8_en    <= 1'b0;

        din    <= fifo_rddata_0;
	end
end
`IP_MODULE_NAME(efx_csi2_crc16_d8_gen) crc16_d8_gen_inst(
    .clk        (clk_byte_HS),
    .rst_n      (reset_byte_HS_n),
    .crc8_en    (crc8_en),
    .din        (din),
    .clr_crc    (clr_crc),
    .crc        (crc)
);
end
endgenerate

logic [15:0] crc_1p, pkt_crc16_1p;
logic check_crc_1p;

always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
    if (!reset_byte_HS_n) begin
        crc_1p       <= 16'h0;
        pkt_crc16_1p <= 16'h0;
        check_crc_1p <= 1'b0;
    end
    else begin 
        crc_1p       <= crc;
        pkt_crc16_1p <= pkt_crc16;
        check_crc_1p <= check_crc;
    end
end

always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
    if (!reset_byte_HS_n) begin
        crc_error <= 1'b0;
    end
    else if (check_crc_1p) begin
        crc_error <= |(pkt_crc16_1p ^ crc_1p);
    end
end
	
endmodule



// synopsys translate_off
`timescale 1 ns / 1 ps													
// synopsys translate_on
/*-------------------------------//

//-------------------------------*/
module `IP_MODULE_NAME(efx_csi2_ecc_check) ( 
  input                 clk_byte_HS,
  input                 reset_byte_HS_n,
  input        [25:0]   pkt_header,
  input        [5:0]    ecc_byte,
  input                 check_ecc,
  output logic [15:0]   wc,
  output logic [1:0]    vc,
  output logic [1:0]    vcx,
  output logic [5:0]    datatype,
  output logic          vld_pkt_header,
  output logic          ecc_1bit_error,   
  output logic          ecc_2bit_error
);


logic [25:0] corrected_pkt_header;
logic [5:0] calculated_ecc;
logic [5:0] syndrome;
logic one_bit_hit;
logic error_flag_1bit, error_flag_2bit; 
logic error_in_ecc_bit, eccbit_error, ecc_no_error, error_in_eccbit_r;
logic parity_bit5, parity_bit4, parity_bit3, parity_bit2, parity_bit1, parity_bit0;

assign parity_bit5 = pkt_header[10] ^ pkt_header[11] ^ pkt_header[12] ^ pkt_header[13] ^ pkt_header[14] ^
                     pkt_header[15] ^ pkt_header[16] ^ pkt_header[17] ^ pkt_header[18] ^ pkt_header[19] ^
                     pkt_header[21] ^ pkt_header[22] ^ pkt_header[23] ^ pkt_header[24] ^ pkt_header[25];
assign parity_bit4 = pkt_header[4] ^ pkt_header[5]  ^ pkt_header[6]  ^ pkt_header[7]  ^ pkt_header[8]  ^
                     pkt_header[9] ^ pkt_header[16] ^ pkt_header[17] ^ pkt_header[18] ^ pkt_header[19] ^
                     pkt_header[20] ^ pkt_header[22] ^ pkt_header[23] ^ pkt_header[24] ^ pkt_header[25];
assign parity_bit3 = pkt_header[1] ^ pkt_header[2] ^ pkt_header[3] ^ pkt_header[7] ^ pkt_header[8] ^
                     pkt_header[9] ^ pkt_header[13] ^ pkt_header[14] ^ pkt_header[15] ^ pkt_header[19] ^
                     pkt_header[20] ^ pkt_header[21] ^ pkt_header[23] ^ pkt_header[24] ^ pkt_header[25];
assign parity_bit2 = pkt_header[0] ^ pkt_header[2] ^ pkt_header[3] ^ pkt_header[5] ^ pkt_header[6] ^
                     pkt_header[9] ^ pkt_header[11] ^ pkt_header[12] ^ pkt_header[15] ^ pkt_header[18] ^
                     pkt_header[20] ^ pkt_header[21] ^ pkt_header[22] ^ pkt_header[24] ^ pkt_header[25];
assign parity_bit1 = pkt_header[0] ^ pkt_header[1] ^ pkt_header[3] ^  pkt_header[4] ^ pkt_header[6] ^
                     pkt_header[8] ^ pkt_header[10] ^ pkt_header[12] ^ pkt_header[14] ^ pkt_header[17] ^
                     pkt_header[20] ^ pkt_header[21] ^ pkt_header[22] ^ pkt_header[23] ^ pkt_header[25];
assign parity_bit0 = pkt_header[0] ^ pkt_header[1] ^ pkt_header[2] ^ pkt_header[4] ^ pkt_header[5] ^
                     pkt_header[7] ^ pkt_header[10] ^ pkt_header[11] ^ pkt_header[13] ^ pkt_header[16] ^
                     pkt_header[20] ^ pkt_header[21] ^ pkt_header[22] ^ pkt_header[23] ^ pkt_header[24];
              
assign calculated_ecc = {parity_bit5,parity_bit4,parity_bit3,
                         parity_bit2,parity_bit1,parity_bit0};
assign syndrome = ecc_byte ^ calculated_ecc;
assign error_flag_1bit  = (syndrome != 8'h00)
                            &&  one_bit_hit && check_ecc;
assign error_flag_2bit  = (syndrome != 8'h00) && (!one_bit_hit)
                            && check_ecc & !error_in_ecc_bit;
assign error_in_ecc_bit = (error_in_eccbit_r) | (!error_in_eccbit_r) && check_ecc;

always @(*) begin
    one_bit_hit	     = 1'b0;
    corrected_pkt_header   = pkt_header;
    error_in_eccbit_r  = 1'b0;
    case(syndrome[5:0])     
        6'h07:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:1],!pkt_header[0]};
	    end	    
	    6'h0B:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:2],!pkt_header[1],pkt_header[0]};
	    end
	    6'h0D:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:3],!pkt_header[2],pkt_header[1:0]};
	    end
	    6'h0E:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:4],!pkt_header[3],pkt_header[2:0]}; 
	    end
	    6'h13:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:5],!pkt_header[4],pkt_header[3:0]}; 
	    end
	    6'h15:
	    begin
	     one_bit_hit      = 1'b1;    
	    corrected_pkt_header = {pkt_header[25:6],!pkt_header[5],pkt_header[4:0]};
	    end
	    6'h16:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:7],!pkt_header[6],pkt_header[5:0]};
	    end
	    6'h19:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:8],!pkt_header[7],pkt_header[6:0]};
	    end
	    6'h1A:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:9],!pkt_header[8],pkt_header[7:0]};	   
	    end
	    6'h1C:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:10],!pkt_header[9],pkt_header[8:0]};	    
	    end
	    6'h23:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:11],!pkt_header[10],pkt_header[9:0]};  	      
	    end
	    6'h25:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:12],!pkt_header[11],pkt_header[10:0]};       
	    end
	    6'h26:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:13],!pkt_header[12],pkt_header[11:0]};       
	    end
	    6'h29:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:14],!pkt_header[13],pkt_header[12:0]};       
	    end
	    6'h2A:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:15],!pkt_header[14],pkt_header[13:0]};       
	    end
	    6'h2C:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:16],!pkt_header[15],pkt_header[14:0]};       
	    end	
	    6'h31:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:17],!pkt_header[16],pkt_header[15:0]};       
	    end
	    6'h32:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:18],!pkt_header[17],pkt_header[16:0]};       
	    end	
	    6'h34:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:19],!pkt_header[18],pkt_header[17:0]};       
	    end	   
	    6'h38:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:20],!pkt_header[19],pkt_header[18:0]};       
	    end	      
	    6'h1F:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:21],!pkt_header[20],pkt_header[19:0]};       
	    end		 
	    6'h2F:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:22],!pkt_header[21],pkt_header[20:0]};       
	    end		    
	    6'h37:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:23],!pkt_header[22],pkt_header[21:0]};	   
	    end		       
	    6'h3B:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25:24],!pkt_header[23],pkt_header[22:0]};	
	    end	
	    
	    6'h3D:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {pkt_header[25],!pkt_header[24],pkt_header[23:0]};	   
	    end		       
	    6'h3B:
	    begin
	     one_bit_hit      = 1'b1;
	     corrected_pkt_header = {!pkt_header[25],pkt_header[24:0]};	
	    end	
        6'b00_0001:
        begin
         error_in_eccbit_r = 1'b1;
        end
        6'b00_0010:
        begin
         error_in_eccbit_r = 1'b1;
        end
        6'b00_0100:
        begin
         error_in_eccbit_r = 1'b1;
        end
        6'b00_1000:
        begin
         error_in_eccbit_r = 1'b1;
        end
        6'b01_0000:
        begin
         error_in_eccbit_r = 1'b1;
        end
        6'b10_0000:
        begin
         error_in_eccbit_r = 1'b1;
        end
	    default: begin
	        one_bit_hit        = 1'b0 ;
	        corrected_pkt_header   = pkt_header;
            error_in_eccbit_r = 1'b0;
	    end
    endcase
end

always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        ecc_no_error <= 1'b0;
    else if(check_ecc & !error_flag_1bit & !error_flag_2bit & !error_in_ecc_bit)
        ecc_no_error <= 1'b1;
    else
        ecc_no_error <= 1'b0;
        
always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        ecc_1bit_error <= 1'b0;
    else if(check_ecc)
        ecc_1bit_error <= error_flag_1bit;
        
always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        ecc_2bit_error <= 1'b0;
    else if(check_ecc) 
        ecc_2bit_error <= error_flag_2bit;
     
always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        eccbit_error <= 1'b0;
    else if(check_ecc)
        eccbit_error <= error_in_ecc_bit;
    else
        eccbit_error <= 1'b0;
        
always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        vc <= 2'b0;
    else if (check_ecc & !error_flag_2bit)
        vc <= corrected_pkt_header[7:6];
        
always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        vcx <= 2'b0;
    else if (check_ecc & !error_flag_2bit)
        vcx <= corrected_pkt_header[25:24];
        
always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        datatype <= 6'b0; 
    else if (check_ecc & !error_flag_2bit)
        datatype <= corrected_pkt_header[5:0];
       
always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        wc <= 16'b0; 
    else if (check_ecc & !error_flag_2bit)
        wc <= corrected_pkt_header[23:8];
    
always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
    if (!reset_byte_HS_n)
        vld_pkt_header  <= 1'b0; 
    else
        vld_pkt_header <= (check_ecc & !error_flag_2bit);
        
        
endmodule



