    output logic          vsync_vc4,
    output logic          vsync_vc5,
    output logic          vsync_vc6,
    output logic          vsync_vc7,
    output logic          vsync_vc8,
    output logic          vsync_vc9,
    output logic          vsync_vc10,
    output logic          vsync_vc11,
    output logic          vsync_vc12,
    output logic          vsync_vc13,
    output logic          vsync_vc14,
    output logic          vsync_vc15,
    
    output logic [1:0]    vc,
    output logic [1:0]    vcx,
    output logic [15:0]   word_count,
    output logic [15:0]   shortpkt_data_field,
    output logic [5:0]    datatype,
    output logic [3:0]    pixel_per_clk,
    output logic [63:0]   pixel_data,
    output logic          pixel_data_valid,
    output logic          irq
);

localparam CLOCK_PERIOD_NS = 1000/(CLOCK_FREQ_MHZ);    // must be >= 40Mhz
localparam tINIT = ((tINIT_NS + CLOCK_PERIOD_NS-1) / CLOCK_PERIOD_NS); //min=100us
localparam ACTUAL_DATA_LANE = (HS_DATA_WIDTH == 16) ? NUM_DATA_LANE*2 : NUM_DATA_LANE;

genvar j;
logic init_done, pixel_fifo_empty, pixel_fifo_full;
logic fifo_rddata_valid;
logic [ACTUAL_DATA_LANE-1:0] fifo_empty, fifo_read;
logic [ACTUAL_DATA_LANE-1:0][7:0] fifo_rddata_o;
logic [3:0] actual_pixel_count;
logic [3:0] extra_pixel_count;
logic [AREGISTER-1:0] RxStopState_reg;
logic [17:0] init_cnt;
logic [63:0] pkt_data;
logic receive_error, ready_to_rcv, ecc_2bit_error, ecc_1bit_error;
logic frame_sync_vc0_error, frame_sync_vc1_error, frame_sync_vc2_error, frame_sync_vc3_error;
logic line_sync_vc0_error, line_sync_vc1_error, line_sync_vc2_error, line_sync_vc3_error;
logic crc_error, undersize_pkt_error;
logic valid_pkt_data, trigger_extra_pixel, odd_line;
logic RAW6_r, RAW7_r, RAW8_r, RAW10_r, RAW12_r, RAW14_r, RAW20_r;
logic RGB444_r, RGB555_r, RGB565_r, RGB888_r;
logic YUV_422_8_r, YUV_422_10_r, YUV_420_8_legacy_r, YUV_420_8_r, YUV_420_10_r;
logic user_define_8bit_r, embed_8bit_nonvideo_r, gen_long_pkt_r;
logic [15:0] hsync_vc_int, vsync_vc_int;
logic RxStopState_int, RxStopState_o;
logic RxValidHS, RxValidHS_sync, ready_to_rcv_sync;
logic [NUM_DATA_LANE-1:0] RxStopState_sync, RxErrSotSyncHS_o;

assign init_done = (init_cnt == tINIT);
assign shortpkt_data_field = word_count;
assign RxStopState_int = |RxStopState;
assign pixel_per_clk = (trigger_extra_pixel) ? extra_pixel_count : actual_pixel_count;

`IP_MODULE_NAME(efx_asyncreg) #(.ASYNC_STAGE(ASYNC_STAGE), .WIDTH(1)) syncreg_0 (.clk(clk), .reset_n(reset_n), .d_i(RxValidHS), .d_o(RxValidHS_sync));
`IP_MODULE_NAME(efx_asyncreg) #(.ASYNC_STAGE(ASYNC_STAGE), .WIDTH(1)) syncreg_1 (.clk(clk_byte_HS), .reset_n(reset_byte_HS_n), .d_i(ready_to_rcv), .d_o(ready_to_rcv_sync));
`IP_MODULE_NAME(efx_asyncreg) #(.ASYNC_STAGE(ASYNC_STAGE), .WIDTH(NUM_DATA_LANE)) syncreg_2 (.clk(clk_byte_HS), .reset_n(reset_byte_HS_n), .d_i(RxStopState), .d_o(RxStopState_sync));

always @ (posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        init_cnt    <= 18'd0;
    end
    else if (init_cnt < tINIT) begin
    	init_cnt    <= init_cnt + 18'd1;
    end
end

always @ (posedge clk or negedge reset_n)
    if (!reset_n) 
        ready_to_rcv <= 1'b0;
    else if(init_done & RxStopState_int)
        ready_to_rcv <= 1'b1;
        
always @ (posedge clk or negedge reset_n)
    if (!reset_n) 
        receive_error <= 1'b0;
    else if(!init_done & RxValidHS_sync)
        receive_error <= 1'b1;

generate
//--- introduce additional registers to compensate DPHY + controller + HSIO latency ---//
for (j=0; j<AREGISTER; j++) begin
    if (j==0) begin
        always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
        begin
            if(!reset_byte_HS_n)begin
                RxStopState_reg[0]    <= 1'b1;
        	end
        	else begin
                RxStopState_reg[0]    <= |RxStopState_sync;
            end
        end
    end
    else begin
        always @ (posedge clk_byte_HS or negedge reset_byte_HS_n)
        begin
            if(!reset_byte_HS_n)begin
                RxStopState_reg[j]    <= 1'b1;
        	end
        	else begin
                RxStopState_reg[j]    <= RxStopState_reg[j-1];
            end
        end
    end
end
endgenerate
assign RxStopState_o = RxStopState_reg[AREGISTER-1];

always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
	if(!reset_byte_HS_n)begin
        RxErrSotSyncHS_o <= 1'b0;
	end
	else begin
	    RxErrSotSyncHS_o <= RxErrSotSyncHS;
	end
end

