    .axi_bvalid              (axi_bvalid),
    .axi_bready              (axi_bready),
    .axi_araddr              (axi_araddr),
    .axi_arvalid             (axi_arvalid),
    .axi_arready             (axi_arready),
    .axi_rdata               (axi_rdata),
    .axi_rvalid              (axi_rvalid),
    .axi_rready              (axi_rready),
    .receive_error           (receive_error),
    .pixel_fifo_full         (pixel_fifo_full),
    .pixel_fifo_empty        (pixel_fifo_empty),
    .ecc_1bit_error          (ecc_1bit_error),
    .ecc_2bit_error          (ecc_2bit_error),
    .frame_sync_vc0_error    (frame_sync_vc0_error),
    .frame_sync_vc1_error    (frame_sync_vc1_error),
    .frame_sync_vc2_error    (frame_sync_vc2_error),
    .frame_sync_vc3_error    (frame_sync_vc3_error),
    .line_sync_vc0_error     (line_sync_vc0_error),
    .line_sync_vc1_error     (line_sync_vc1_error),
    .line_sync_vc2_error     (line_sync_vc2_error),
    .line_sync_vc3_error     (line_sync_vc3_error),
    .crc_error               (crc_error),
    .undersize_pkt_error     (undersize_pkt_error),
	.RxUlpsClkNot            (RxUlpsClkNot),
	.RxUlpsActiveClkNot      (RxUlpsActiveClkNot),
    .RxErrEsc                (RxErrEsc),
    .RxErrControl            (RxErrControl),
    .RxErrSotSyncHS          (RxErrSotSyncHS_o),
    .RxClkEsc                (RxClkEsc),
    .RxUlpsEsc               (RxUlpsEsc),
    .RxUlpsActiveNot         (RxUlpsActiveNot),
    .RxSkewCalHS             (RxSkewCalHS),
    .RxStopState             (RxStopState),            
    .irq                     (irq)
);

`IP_MODULE_NAME(efx_csi2_depacketizer) #(
   .ENABLE_VCX       (ENABLE_VCX),
   .FRAME_MODE       (FRAME_MODE),
   .NUM_DATA_LANE    (ACTUAL_DATA_LANE)
) depacketizer_inst (
    .clk_byte_HS             (clk_byte_HS),
    .reset_byte_HS_n         (reset_byte_HS_n),
    .RxStopState             (RxStopState_o),
    .fifo_rddata_o           (fifo_rddata_o),
    .fifo_empty              (fifo_empty),
    .fifo_read               (fifo_read),
    .vc                      (vc),
	.vcx                     (vcx),
    .word_count              (word_count),
    .actual_pixel_count      (actual_pixel_count),
    .datatype                (datatype),
    .ecc_1bit_error          (ecc_1bit_error),
    .ecc_2bit_error          (ecc_2bit_error),
    .frame_sync_vc0_error    (frame_sync_vc0_error),
    .frame_sync_vc1_error    (frame_sync_vc1_error),
    .frame_sync_vc2_error    (frame_sync_vc2_error),
    .frame_sync_vc3_error    (frame_sync_vc3_error),
    .line_sync_vc0_error     (line_sync_vc0_error),
    .line_sync_vc1_error     (line_sync_vc1_error),
    .line_sync_vc2_error     (line_sync_vc2_error),
    .line_sync_vc3_error     (line_sync_vc3_error),
    .crc_error               (crc_error),
    .undersize_pkt_error     (undersize_pkt_error),
	.hsync_vc                (hsync_vc_int),
	.vsync_vc                (vsync_vc_int),
    .pkt_data                (pkt_data),
    .valid_pkt_data          (valid_pkt_data),
    .odd_line                (odd_line),
    .RAW6_r                  (RAW6_r),
    .RAW7_r                  (RAW7_r),
    .RAW8_r                  (RAW8_r),
    .RAW10_r                 (RAW10_r),
    .RAW12_r                 (RAW12_r),
    .RAW14_r                 (RAW14_r),
    .RAW20_r                 (RAW20_r),
    .RGB444_r                (RGB444_r),
    .RGB555_r                (RGB555_r),
    .RGB565_r                (RGB565_r),
    .RGB888_r                (RGB888_r),
    .YUV_422_8_r             (YUV_422_8_r),
    .YUV_422_10_r            (YUV_422_10_r),
	.YUV_420_8_legacy_r      (YUV_420_8_legacy_r),
	.YUV_420_8_r             (YUV_420_8_r),
	.YUV_420_10_r            (YUV_420_10_r),
	.gen_long_pkt_r          (gen_long_pkt_r),
	.embed_8bit_nonvideo_r   (embed_8bit_nonvideo_r),
	.user_define_8bit_r      (user_define_8bit_r)
);

generate
if (HS_DATA_WIDTH == 8) begin
    logic [(NUM_DATA_LANE)-1:0] RxValidHS_int;
    logic [(NUM_DATA_LANE)-1:0][7:0] RxDataHS_int;
    
    if (NUM_DATA_LANE == 1) begin
        assign RxValidHS_int[0] = RxValidHS0;
        assign RxDataHS_int[0]  = RxDataHS0;
    end
    else if (NUM_DATA_LANE == 2) begin
        assign RxValidHS_int[0] = RxValidHS0;
        assign RxValidHS_int[1] = RxValidHS1;
        assign RxDataHS_int[0]  = RxDataHS0;
        assign RxDataHS_int[1]  = RxDataHS1;
    end
    else if (NUM_DATA_LANE == 4) begin
        assign RxValidHS_int[0] = RxValidHS0;
        assign RxValidHS_int[1] = RxValidHS1;
        assign RxValidHS_int[2] = RxValidHS2;
        assign RxValidHS_int[3] = RxValidHS3;
        assign RxDataHS_int[0]  = RxDataHS0;
        assign RxDataHS_int[1]  = RxDataHS1;
        assign RxDataHS_int[2]  = RxDataHS2;
        assign RxDataHS_int[3]  = RxDataHS3;
    end
    else if (NUM_DATA_LANE == 8) begin
        assign RxValidHS_int[0] = RxValidHS0;
        assign RxValidHS_int[1] = RxValidHS1;
        assign RxValidHS_int[2] = RxValidHS2;
        assign RxValidHS_int[3] = RxValidHS3;
        assign RxValidHS_int[4] = RxValidHS4;
        assign RxValidHS_int[5] = RxValidHS5;
        assign RxValidHS_int[6] = RxValidHS6;
        assign RxValidHS_int[7] = RxValidHS7;
        assign RxDataHS_int[0]  = RxDataHS0;
        assign RxDataHS_int[1]  = RxDataHS1;
        assign RxDataHS_int[2]  = RxDataHS2;
        assign RxDataHS_int[3]  = RxDataHS3;
        assign RxDataHS_int[4]  = RxDataHS4;
        assign RxDataHS_int[5]  = RxDataHS5;
        assign RxDataHS_int[6]  = RxDataHS6;
        assign RxDataHS_int[7]  = RxDataHS7;
    end
    
    `IP_MODULE_NAME(efx_csi2_lane_aligner) #(
        .NUM_DATA_LANE    (ACTUAL_DATA_LANE)
    ) lane_aligner_inst (
        .clk_byte_HS        (clk_byte_HS),
        .reset_byte_HS_n    (reset_byte_HS_n),
        .ready_to_rcv       (ready_to_rcv_sync),
        .RxDataHS           (RxDataHS_int),
        .RxValidHS          (RxValidHS_int),
        .RxSyncHS           (RxSyncHS),
        .fifo_read          (fifo_read),
        .fifo_empty         (fifo_empty),
        .fifo_rddata_o      (fifo_rddata_o)
    );
    
    assign RxValidHS = |RxValidHS_int;
end
else begin
    logic [(NUM_DATA_LANE*2)-1:0] RxValidHS_int;
    logic [(NUM_DATA_LANE*2)-1:0] RxSyncHS_int;
    logic [(NUM_DATA_LANE*2)-1:0][7:0] RxDataHS_int;
    
    if (NUM_DATA_LANE == 1) begin
        assign RxValidHS_int[0] = RxValidHS0[0];
        assign RxValidHS_int[1] = RxValidHS0[1];
        assign RxSyncHS_int[0] = RxSyncHS[0];
        assign RxSyncHS_int[1] = RxSyncHS[0];
        assign RxDataHS_int[0] = RxDataHS0[7:0];
        assign RxDataHS_int[1] = RxDataHS0[15:8];
    end
    else if (NUM_DATA_LANE == 2) begin
        assign RxValidHS_int[0] = RxValidHS0[0];
        assign RxValidHS_int[1] = RxValidHS1[0];
        assign RxValidHS_int[2] = RxValidHS0[1];
        assign RxValidHS_int[3] = RxValidHS1[1];
        assign RxSyncHS_int[0] = RxSyncHS[0];
        assign RxSyncHS_int[1] = RxSyncHS[1];
        assign RxSyncHS_int[2] = RxSyncHS[0];
        assign RxSyncHS_int[3] = RxSyncHS[1];
        assign RxDataHS_int[0] = RxDataHS0[7:0]; //RxDataHS0[7:0];
        assign RxDataHS_int[1] = RxDataHS1[7:0]; //RxDataHS0[15:8];
        assign RxDataHS_int[2] = RxDataHS0[15:8]; //RxDataHS1[7:0];
        assign RxDataHS_int[3] = RxDataHS1[15:8]; //RxDataHS1[15:8];
    end
    else begin  //NUM_DATA_LANE == 4 or 8, 8 is not valid usecase though
        assign RxValidHS_int[0] = RxValidHS0[0];
        assign RxValidHS_int[1] = RxValidHS1[0];
        assign RxValidHS_int[2] = RxValidHS2[0];
        assign RxValidHS_int[3] = RxValidHS3[0];
        assign RxValidHS_int[4] = RxValidHS0[1];
        assign RxValidHS_int[5] = RxValidHS1[1];
        assign RxValidHS_int[6] = RxValidHS2[1];
        assign RxValidHS_int[7] = RxValidHS3[1];
        assign RxSyncHS_int[0] = RxSyncHS[0];
        assign RxSyncHS_int[1] = RxSyncHS[1];
        assign RxSyncHS_int[2] = RxSyncHS[2];
        assign RxSyncHS_int[3] = RxSyncHS[3];
        assign RxSyncHS_int[4] = RxSyncHS[0];
        assign RxSyncHS_int[5] = RxSyncHS[1];
        assign RxSyncHS_int[6] = RxSyncHS[2];
        assign RxSyncHS_int[7] = RxSyncHS[3];
        assign RxDataHS_int[0] = RxDataHS0[7:0]; //RxDataHS0[7:0];
        assign RxDataHS_int[1] = RxDataHS1[7:0]; //RxDataHS0[15:8];
        assign RxDataHS_int[2] = RxDataHS2[7:0]; //RxDataHS1[7:0];
        assign RxDataHS_int[3] = RxDataHS3[7:0]; //RxDataHS1[15:8];
        assign RxDataHS_int[4] = RxDataHS0[15:8]; //RxDataHS2[7:0];
        assign RxDataHS_int[5] = RxDataHS1[15:8]; //RxDataHS2[15:8];
        assign RxDataHS_int[6] = RxDataHS2[15:8]; //RxDataHS3[7:0];
        assign RxDataHS_int[7] = RxDataHS3[15:8]; //RxDataHS3[15:8];
    end
    
    `IP_MODULE_NAME(efx_csi2_lane_aligner) #(
        .NUM_DATA_LANE    (ACTUAL_DATA_LANE)
    ) lane_aligner_inst (
        .clk_byte_HS        (clk_byte_HS),
        .reset_byte_HS_n    (reset_byte_HS_n),
        .ready_to_rcv       (ready_to_rcv_sync),
        .RxDataHS           (RxDataHS_int),
        .RxValidHS          (RxValidHS_int),
        .RxSyncHS           (RxSyncHS_int),
        .fifo_read          (fifo_read),
        .fifo_empty         (fifo_empty),
        .fifo_rddata_o      (fifo_rddata_o)
    );
    
    assign RxValidHS = |RxValidHS_int;
end

