assign RxErrControl_3 = RxErrControl_sync[3];
assign RxErrSotSyncHS_3 = RxErrSotSyncHS_sync[3];
assign RxUlpsEsc_3 = RxUlpsEsc_sync[3];
assign RxUlpsActiveNot_3 = RxUlpsActiveNot_sync[3];
assign RxSkewCalHS_3 = RxSkewCalHS_sync[3];
assign RxStopState_3 = RxStopState_sync[3];

assign RxErrEsc_4 = RxErrEsc_sync[4];
assign RxErrControl_4 = RxErrControl_sync[4];
assign RxErrSotSyncHS_4 = RxErrSotSyncHS_sync[4];
assign RxUlpsEsc_4 = RxUlpsEsc_sync[4];
assign RxUlpsActiveNot_4 = RxUlpsActiveNot_sync[4];
assign RxSkewCalHS_4 = RxSkewCalHS_sync[4];
assign RxStopState_4 = RxStopState_sync[4];

assign RxErrEsc_5 = RxErrEsc_sync[5];
assign RxErrControl_5 = RxErrControl_sync[5];
assign RxErrSotSyncHS_5 = RxErrSotSyncHS_sync[5];
assign RxUlpsEsc_5 = RxUlpsEsc_sync[5];
assign RxUlpsActiveNot_5 = RxUlpsActiveNot_sync[5];
assign RxSkewCalHS_5 = RxSkewCalHS_sync[5];
assign RxStopState_5 = RxStopState_sync[5];

assign RxErrEsc_6 = RxErrEsc_sync[6];
assign RxErrControl_6 = RxErrControl_sync[6];
assign RxErrSotSyncHS_6 = RxErrSotSyncHS_sync[6];
assign RxUlpsEsc_6 = RxUlpsEsc_sync[6];
assign RxUlpsActiveNot_6 = RxUlpsActiveNot_sync[6];
assign RxSkewCalHS_6 = RxSkewCalHS_sync[6];
assign RxStopState_6 = RxStopState_sync[6];

assign RxErrEsc_7 = RxErrEsc_sync[7];
assign RxErrControl_7 = RxErrControl_sync[7];
assign RxErrSotSyncHS_7 = RxErrSotSyncHS_sync[7];
assign RxUlpsEsc_7 = RxUlpsEsc_sync[7];
assign RxUlpsActiveNot_7 = RxUlpsActiveNot_sync[7];
assign RxSkewCalHS_7 = RxSkewCalHS_sync[7];
assign RxStopState_7 = RxStopState_sync[7];
end
endgenerate

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        loc_waddr <= {4{1'b0}};
	else if((axi_awvalid == 1'b1) && (axi_awready == 1'b1))
		loc_waddr <= axi_awaddr[5:2];
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        loc_waddr_vld <= 1'b0;
	else if((axi_awvalid == 1'b1) && (axi_awready == 1'b1))
		loc_waddr_vld <= 1'b1;
    else if((loc_waddr_vld == 1'b1) && (loc_wdata_vld == 1'b1))
        loc_waddr_vld <= 1'b0;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        axi_awready <= 1'b0;
	else if((axi_awvalid == 1'b1) && (axi_awready == 1'b1))
		axi_awready <= 1'b0;
	else if(loc_waddr_vld == 1'b0)
		axi_awready <= 1'b1;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        loc_wdata <= 32'h0;
	else if((axi_wvalid == 1'b1) && (axi_wready == 1'b1))
		loc_wdata <= axi_wdata;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        loc_wdata_vld <= 1'b0;
	else if((axi_wvalid == 1'b1) && (axi_wready == 1'b1))
		loc_wdata_vld <= 1'b1;
    else if((loc_waddr_vld == 1'b1) && (loc_wdata_vld == 1'b1))
        loc_wdata_vld <= 1'b0;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        axi_wready <= 1'b0;
	else if((axi_wvalid == 1'b1) && (axi_wready == 1'b1))
		axi_wready <= 1'b0;
	else if(loc_wdata_vld == 1'b0)
		axi_wready <= 1'b1;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        axi_bvalid <= 1'b0;
	else if((loc_waddr_vld == 1'b1) && (loc_wdata_vld == 1'b1))
		axi_bvalid <= 1'b1;
    else if(axi_bready == 1'b1)
        axi_bvalid <= 1'b0;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        loc_raddr <= {4{1'b0}};
	else if((axi_arvalid == 1'b1) && (axi_arready == 1'b1))
		loc_raddr <= axi_araddr[5:2];
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        loc_raddr_vld <= 1'b0;
	else if((axi_arvalid == 1'b1) && (axi_arready == 1'b1))
		loc_raddr_vld <= 1'b1;
    else if(loc_raddr_vld == 1'b1)
        loc_raddr_vld <= 1'b0;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        axi_arready <= 1'b0;
	else if((axi_arvalid == 1'b1) && (axi_arready == 1'b1))
		axi_arready <= 1'b0;
	else if(loc_raddr_vld == 1'b0)
		axi_arready <= 1'b1;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        axi_rvalid <= 1'b0;
	else if(loc_raddr_vld == 1'b1)
        axi_rvalid <= 1'b1;
    else if(axi_rready == 1'b1)
        axi_rvalid <= 1'b0;
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n) begin
        axi_rdata <= 32'h0;
    end
	else if(loc_raddr_vld == 1'b1) begin
		case(loc_raddr)
            'h00 : axi_rdata <= {17'h0, status};
            'h01 : axi_rdata <= {17'h0, interrupt_enable};
            'h02 : axi_rdata <= {25'h0, rxdphy_status0};
            'h03 : axi_rdata <= {25'h0, rxdphy_status1};
            'h04 : axi_rdata <= {25'h0, rxdphy_status2};
            'h05 : axi_rdata <= {25'h0, rxdphy_status3};
            'h06 : axi_rdata <= {25'h0, rxdphy_status4};
            'h07 : axi_rdata <= {25'h0, rxdphy_status5};
            'h08 : axi_rdata <= {25'h0, rxdphy_status6};
            'h09 : axi_rdata <= {25'h0, rxdphy_status7}; 
            'h0A : axi_rdata <= {30'h0, rxdphyclk_status};
        endcase
    end
end

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n)
        interrupt_enable    <= 15'h0;
	else if((axi_bvalid == 1'b1) && (loc_waddr == 'h01))
        interrupt_enable    <= loc_wdata[14:0];
end

assign rxdphy_status0 = {RxUlpsEsc_0, RxUlpsActiveNot_0, RxSkewCalHS_0, RxStopState_0,
                        RxErrEsc_0, RxErrControl_0, RxErrSotSyncHS_0};
                        
assign rxdphy_status1 = {RxUlpsEsc_1, RxUlpsActiveNot_1, RxSkewCalHS_1, RxStopState_1,
                        RxErrEsc_1, RxErrControl_1, RxErrSotSyncHS_1};

assign rxdphy_status2 = {RxUlpsEsc_2, RxUlpsActiveNot_2, RxSkewCalHS_2, RxStopState_2,
                        RxErrEsc_2, RxErrControl_2, RxErrSotSyncHS_2};
                        
assign rxdphy_status3 = {RxUlpsEsc_3, RxUlpsActiveNot_3, RxSkewCalHS_3, RxStopState_3,
                        RxErrEsc_3, RxErrControl_3, RxErrSotSyncHS_3};
                        
assign rxdphy_status4 = {RxUlpsEsc_4, RxUlpsActiveNot_4, RxSkewCalHS_4, RxStopState_4,
                        RxErrEsc_4, RxErrControl_4, RxErrSotSyncHS_4};
                        
assign rxdphy_status5 = {RxUlpsEsc_5, RxUlpsActiveNot_5, RxSkewCalHS_5, RxStopState_5,
                        RxErrEsc_5, RxErrControl_5, RxErrSotSyncHS_5};

assign rxdphy_status6 = {RxUlpsEsc_6, RxUlpsActiveNot_6, RxSkewCalHS_6, RxStopState_6,
                        RxErrEsc_6, RxErrControl_6, RxErrSotSyncHS_6};
                        
assign rxdphy_status7 = {RxUlpsEsc_7, RxUlpsActiveNot_7, RxSkewCalHS_7, RxStopState_7,
                        RxErrEsc_7, RxErrControl_7, RxErrSotSyncHS_7};
                        
assign rxdphyclk_status = {RxUlpsClkNot, RxUlpsActiveClkNot};

always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n) begin
        crc_error_reg           <= 1'b0;
        ecc_1bit_error_reg      <= 1'b0;
        ecc_2bit_error_reg      <= 1'b0;
        undersize_pkt_error_reg <= 1'b0;
        line_sync_vc0_error_reg <= 1'b0;
        line_sync_vc1_error_reg <= 1'b0;
        line_sync_vc2_error_reg <= 1'b0;
        line_sync_vc3_error_reg <= 1'b0;
        frame_sync_vc0_error_reg<= 1'b0;
        frame_sync_vc1_error_reg<= 1'b0;
        frame_sync_vc2_error_reg<= 1'b0;
        frame_sync_vc3_error_reg<= 1'b0;
        receive_error_reg       <= 1'b0;
    end
    else begin
        crc_error_reg           <= crc_error_sync;
        ecc_1bit_error_reg      <= ecc_1bit_error_sync;
        ecc_2bit_error_reg      <= ecc_2bit_error_sync;
        undersize_pkt_error_reg <= undersize_pkt_error_sync;
        line_sync_vc0_error_reg <= line_sync_vc0_error_sync;
        line_sync_vc1_error_reg <= line_sync_vc1_error_sync; 
        line_sync_vc2_error_reg <= line_sync_vc2_error_sync; 
        line_sync_vc3_error_reg <= line_sync_vc3_error_sync; 
        frame_sync_vc0_error_reg<= frame_sync_vc0_error_sync;
        frame_sync_vc1_error_reg<= frame_sync_vc1_error_sync;
        frame_sync_vc2_error_reg<= frame_sync_vc2_error_sync;
        frame_sync_vc3_error_reg<= frame_sync_vc3_error_sync;
        receive_error_reg       <= receive_error_sync;
    end
end
                            
always @(posedge axi_clk or negedge axi_rst_n)
begin
    if(!axi_rst_n) begin
        status    <= 15'h0;
    end
	else begin
		status[0]    <= pixel_fifo_full_sync;
		status[1]    <= pixel_fifo_empty_sync;
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[2] == 'b1)) begin  //W1C
		    status[2]    <= 1'b0;
		end
		else if (crc_error_sync && ~crc_error_reg) begin
		    status[2]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[3] == 'b1)) begin  //W1C
		    status[3]    <= 1'b0;
		end
		else if (ecc_1bit_error_sync && ~ecc_1bit_error_reg) begin
		    status[3]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[4] == 'b1)) begin  //W1C
		    status[4]    <= 1'b0;
		end
		else if (ecc_2bit_error_sync && ~ecc_2bit_error_reg) begin
		    status[4]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[5] == 'b1)) begin  //W1C
		    status[5]    <= 1'b0;
		end
		else if (undersize_pkt_error_sync && ~undersize_pkt_error_reg) begin
		    status[5]    <= 1'b1;
		end
		
		if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[6] == 'b1)) begin  //W1C
		    status[6]    <= 1'b0;
		end
		else if (line_sync_vc0_error_sync && ~line_sync_vc0_error_reg) begin
		    status[6]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[7] == 'b1)) begin  //W1C
		    status[7]    <= 1'b0;
		end
		else if (line_sync_vc1_error_sync && ~line_sync_vc1_error_reg) begin
		    status[7]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[8] == 'b1)) begin  //W1C
		    status[8]    <= 1'b0;
		end
		else if (line_sync_vc2_error_sync && ~line_sync_vc2_error_reg) begin
		    status[8]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[9] == 'b1)) begin  //W1C
		    status[9]    <= 1'b0;
		end
		else if (line_sync_vc3_error_sync && ~line_sync_vc3_error_reg) begin
		    status[9]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[10] == 'b1)) begin  //W1C
		    status[10]    <= 1'b0;
		end
		else if (frame_sync_vc0_error_sync && ~frame_sync_vc0_error_reg) begin
		    status[10]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[11] == 'b1)) begin  //W1C
		    status[11]    <= 1'b0;
		end
		else if (frame_sync_vc1_error_sync && ~frame_sync_vc1_error_reg) begin
		    status[11]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[12] == 'b1)) begin  //W1C
		    status[12]    <= 1'b0;
		end
		else if (frame_sync_vc2_error_sync && ~frame_sync_vc2_error_reg) begin
		    status[12]    <= 1'b1;
		end
		
	    if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[13] == 'b1)) begin  //W1C
		    status[13]    <= 1'b0;
		end
		else if (frame_sync_vc3_error_sync && ~frame_sync_vc3_error_reg) begin
		    status[13]    <= 1'b1;
		end
		
		if((axi_bvalid == 1'b1) && (loc_waddr == 'h00) && (loc_wdata[14] == 'b1)) begin  //W1C
		    status[14]    <= 1'b0;
		end
		else if (receive_error_sync && ~receive_error_reg) begin
		    status[14]    <= 1'b1;
		end
    end
end
                            
assign irq = (status[14] & interrupt_enable[14]) ||
             (status[13] & interrupt_enable[13]) ||
             (status[12] & interrupt_enable[12]) ||
             (status[11] & interrupt_enable[11]) ||
             (status[10] & interrupt_enable[10]) ||
             (status[9] & interrupt_enable[9]) ||
             (status[8] & interrupt_enable[8]) ||
             (status[7] & interrupt_enable[7]) ||
             (status[6] & interrupt_enable[6]) ||
             (status[5] & interrupt_enable[5]) ||
             (status[4] & interrupt_enable[4]) ||
             (status[3] & interrupt_enable[3]) ||
             (status[2] & interrupt_enable[2]) ||
             (status[1] & interrupt_enable[1]) ||
             (status[0] & interrupt_enable[0]);


endmodule


