module `IP_MODULE_NAME(efx_csi2_lane_aligner) #(
    parameter NUM_DATA_LANE = 4
)(
    input  logic                          clk_byte_HS,
    input  logic                          reset_byte_HS_n,	
    input  logic                          ready_to_rcv,
    input  logic [NUM_DATA_LANE-1:0][7:0] RxDataHS,
    input  logic [NUM_DATA_LANE-1:0]      RxValidHS,
    input  logic [NUM_DATA_LANE-1:0]      RxSyncHS,
    input  logic [NUM_DATA_LANE-1:0]      fifo_read,
    output logic [NUM_DATA_LANE-1:0]      fifo_empty,
    output logic [NUM_DATA_LANE-1:0][7:0] fifo_rddata_o
);

genvar i;
logic [NUM_DATA_LANE-1:0] RxValidHS_int;
logic [NUM_DATA_LANE-1:0] sync_detected;

generate
for (i=0; i<NUM_DATA_LANE; i++) begin

always @(posedge clk_byte_HS or negedge reset_byte_HS_n)
begin
    if (~reset_byte_HS_n) begin
        sync_detected[i]    <= 1'b0;
    end
    else begin
        if (RxSyncHS[i]) begin
            sync_detected[i]    <= 1'b1;
        end
        else if (~RxValidHS[i]) begin
            sync_detected[i]    <= 1'b0;
        end
    end
end

assign RxValidHS_int[i] = ready_to_rcv && RxValidHS[i] && sync_detected[i];

`IP_MODULE_NAME(efx_fifo_top) #(
    .SYNC_CLK                   (1                          ),
    .DEPTH                      (16                         ),
    .DATA_WIDTH                 (8                          ),
    .MODE                       ("FWFT"                 ),
    .OUTPUT_REG                 (0                          ),
    .PIPELINE_REG               (1                          ),
    .OPTIONAL_FLAGS             (0                          ),
    .PROGRAMMABLE_FULL          ("NONE"                     ),
    .PROG_FULL_ASSERT           (16                         ),
    .PROG_FULL_NEGATE           (16                         ),
    .PROGRAMMABLE_EMPTY         ("NONE"                     ),
    .PROG_EMPTY_ASSERT          (0                          ),
    .PROG_EMPTY_NEGATE          (0                          )
)
u1_inst
(
//Output
    .almost_full_o              (                           ),
    .prog_full_o                (                           ),
    .full_o                     (                           ),
    .overflow_o                 (                           ),
    .wr_ack_o                   (                           ),
    .datacount_o                (                           ),
    .wr_datacount_o             (                           ),
    .empty_o                    (fifo_empty[i]              ),
    .almost_empty_o             (                           ),
    .prog_empty_o               (                           ),
    .underflow_o                (                           ),
    .rd_valid_o                 (                           ),
    .rdata                      (fifo_rddata_o[i]           ),
    .rd_datacount_o             (                           ),
//Input
    .clk_i                      (clk_byte_HS                ),
    .wr_clk_i                   (1'b0                       ),
    .rd_clk_i                   (1'b0                       ),
    .wr_en_i                    (RxValidHS_int[i]           ),
    .rd_en_i                    (fifo_read[i]               ),
    .a_rst_i                    (!reset_byte_HS_n           ),
    .wdata                      (RxDataHS[i]                )
);

end

endgenerate

endmodule

